window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-06"]={"date":"2026-08-06","dateKR":"2026년 8월 6일","dateEN":"August 6, 2026","total":125,"sections":[{"code":"TOP","kTitle":"주요뉴스","eTitle":"Top News","items":[{"code":"TOP","title":"South Korea weighs nationwide port authority merger","titleKR":"한국, 전국 항만공사 통합 방안 검토","src":"Splash247","date":"2026-08-05","kSum":"한국 정부가 부산·인천 등 개별 항만공사를 하나로 통합하는 전국 단위 항만공사 방안을 검토하고 있다. 항만 경쟁력 강화와 운영 효율화를 목표로 한 구조개편 논의다.","eSum":"South Korea is weighing a merger of its separate port authorities, including Busan and Incheon, into a single nationwide body. The restructuring aims to boost port competitiveness and operational efficiency.","kImp":"세계 주요 환적항인 부산항 등의 거버넌스 개편은 동북아 항만 경쟁 구도에 영향을 줄 수 있다.","eImp":"Reorganising governance of hubs like Busan could reshape Northeast Asian port competition.","url":"https://splash247.com/south-korea-weighs-nationwide-port-authority-merger/"},{"code":"TOP","title":"DP World invests EUR48m in Antwerp cold chain expansion","titleKR":"DP월드(DP World), 앤트워프(Antwerp) 콜드체인 확장에 4,800만 유로 투자","src":"Splash247","date":"2026-08-05","kSum":"DP월드가 벨기에 앤트워프 항만의 냉장·냉동 물류 확장에 4,800만 유로를 투자한다. 신선·냉동 화물 처리 역량을 키워 유럽 콜드체인 물류 허브 지위를 강화하려는 조치다.","eSum":"DP World is investing EUR48m to expand cold chain facilities at the Port of Antwerp. The project boosts reefer and perishable cargo handling capacity as the terminal operator strengthens its European logistics footprint.","kImp":"글로벌 터미널 운영사가 고부가 냉장물류로 사업을 확장하는 흐름을 보여준다.","eImp":"It shows a global terminal operator pushing into higher-value cold chain logistics.","url":"https://splash247.com/dp-world-invests-e48m-in-antwerp-cold-chain-expansion/"},{"code":"TOP","title":"Chinese lessors use Malta flag to rebuild European business","titleKR":"중국 리스사들, 몰타(Malta) 선적 활용해 유럽 사업 재건","src":"Splash247","date":"2026-08-05","kSum":"중국 선박금융 리스사들이 몰타 선적을 활용해 유럽 시장에서 사업을 재구축하고 있다. 지정학·제재 리스크가 커지는 가운데 EU 회원국 국적을 통해 유럽 고객과 금융에 접근하려는 전략이다.","eSum":"Chinese leasing houses are turning to the Malta flag to rebuild their European business. Registering under an EU member state helps them access European clients and financing amid rising geopolitical and sanctions risk.","kImp":"선박금융의 큰손인 중국 리스사들의 규제 회피·시장 재진입 전략을 보여준다.","eImp":"It highlights how China's dominant ship-finance lessors navigate regulation to re-enter European markets.","url":"https://splash247.com/chinese-lessors-use-malta-flag-to-rebuild-european-business/"},{"code":"TOP","title":"Asso.subsea unveiled as buyer of Reach and Eidesvik's IMR vessel","titleKR":"아소서브시(Asso.subsea), 리치·에이데스비크(Reach·Eidesvik) IMR 선박 인수자로 확인","src":"Splash247","date":"2026-08-05","kSum":"그리스 해저 시공사 아소서브시가 리치서브시·에이데스비크 오프쇼어가 보유한 IMR 선박 '바이킹 리치(Viking Reach)'의 인수자로 밝혀졌다. 고사양 작업급 ROV 세트도 함께 인수한다.","eSum":"Greek subsea contractor Asso.subsea has been revealed as the buyer of the Reach Subsea and Eidesvik-owned IMR vessel Viking Reach, along with a high-spec work-class ROV spread. The deal expands its offshore inspection and construction capacity.","kImp":"해저 케이블·풍력 시공 수요 확대 속 오프쇼어 지원선 시장의 활발한 거래를 보여준다.","eImp":"It reflects an active offshore support-vessel S&P market driven by subsea cable and wind demand.","url":"https://splash247.com/asso-subsea-unveiled-as-buyer-of-reach-and-eidesviks-imr-vessel/"},{"code":"TOP","title":"CK Line returns to Huangpu Wenchong for container ships","titleKR":"CK라인(CK Line), 황푸원충(Huangpu Wenchong)에 컨테이너선 재발주","src":"Seatrade Maritime","date":"2026-08-04","kSum":"한국 인트라아시아 선사 CK라인이 중국 황푸원충 조선소에 컨테이너선을 다시 발주했다. 역내 물동량 대응과 선대 현대화를 위한 신조 투자다.","eSum":"Korean intra-Asia carrier CK Line has returned to China's Huangpu Wenchong shipyard to order more container ships. The newbuildings support fleet renewal and regional capacity needs.","kImp":"지역 컨테이너 선사들의 견조한 신조 발주세가 이어지고 있음을 보여준다.","eImp":"It reflects continued newbuilding momentum among regional container carriers.","url":"https://www.seatrade-maritime.com/containers/ck-line-returns-to-huangpu-wenchong-for-container-ships"},{"code":"TOP","title":"EC proposal to approve two Indian ship recyclers comes under fire","titleKR":"EC(유럽집행위)의 인도 선박 재활용 야드 2곳 승인안, 환경단체 반발","src":"Seatrade Maritime","date":"2026-08-04","kSum":"유럽집행위원회가 인도 선박해체 야드 2곳을 EU 승인 리스트에 추가하려 하자 환경단체들이 강하게 반발하고 있다. 해변 좌초(비칭) 방식 해체의 안전·환경 기준 충족 여부를 둘러싼 논란이다.","eSum":"An EU Commission proposal to add two Indian ship recycling yards to its approved list has sparked an environmental backlash. Critics question whether beaching-based dismantling meets EU safety and environmental standards.","kImp":"친환경 선박 재활용 규제와 아시아 해체 야드의 시장 접근을 둘러싼 갈등을 부각한다.","eImp":"It spotlights the clash over green ship-recycling rules and Asian yards' access to EU-flagged tonnage.","url":"https://www.seatrade-maritime.com/regulations/ec-proposal-to-approve-two-indian-ship-recyclers-comes-under-fire"},{"code":"TOP","title":"MISC adds LNG carrier newbuild at Hudong-Zhonghua","titleKR":"MISC, 후동중화(Hudong-Zhonghua)에 소형 LNG선 신조 추가 발주","src":"Seatrade Maritime","date":"2026-08-03","kSum":"말레이시아 MISC가 후동중화조선에 1만8,700㎥급 멤브레인형 LNG운반선을 추가 발주했다. 올해 초 체결한 5+5척 대형 LNG선 계약에 이은 후속 발주로, 후동중화의 LNG선 수주잔량은 약 60척으로 늘었다.","eSum":"Malaysia's MISC has ordered an 18,700-cbm membrane-type LNG carrier at Hudong-Zhonghua, a follow-up to a 5+5 large LNG carrier deal earlier in 2026. The contract lifts the yard's LNG orderbook to nearly 60 vessels, with deliveries stretching beyond 2030.","kImp":"중국 조선소의 LNG선 수주 독주와 MISC의 가스선 확장 전략을 동시에 보여준다.","eImp":"It underscores both Chinese yards' dominance in LNG shipbuilding and MISC's continued gas-fleet expansion.","url":"https://www.seatrade-maritime.com/tankers/misc-adds-lng-carrier-newbuild-at-hudong-zhonghua"},{"code":"TOP","title":"HD Hyundai launches first vessel built at revived Subic Bay shipyard","titleKR":"HD현대(HD Hyundai), 부활한 필리핀 수빅베이(Subic Bay) 조선소서 첫 선박 진수","src":"gCaptain","date":"2026-07-31","kSum":"HD현대가 필리핀 수빅베이 조선소에서 자사 인수 후 첫 건조 선박 '오리온 제이드(Orion Jade)'를 진수했다. 옛 한진중공업 부지를 되살린 이 야드는 현재 약 4,000명을 고용 중이며 향후 배로 늘어날 전망이다.","eSum":"HD Hyundai has launched Orion Jade, the first ship completed at its Subic Bay yard since taking over the former Hanjin facility. The 250-metre vessel marks the start of full-scale commercial shipbuilding at a yard employing nearly 4,000 workers.","kImp":"한국 조선사의 동남아 생산기지 확대와 필리핀 조선산업 재건을 상징한다.","eImp":"It signals Korean shipbuilders' expansion into Southeast Asian capacity and the revival of Philippine shipbuilding.","url":"https://gcaptain.com/hd-hyundai-launches-first-vessel-built-at-revived-subic-bay-shipyard/"}]},{"code":"ACC","type":"accident","kTitle":"사고","eTitle":"Accidents","items":[{"code":"ACC","type":"accident","title":"Houthis claim missile attack on Saudi oil tanker Wafa in northern Red Sea off Yanbu","titleKR":"후티, 홍해 북부 얀부 앞바다서 사우디 유조선 Wafa(와파) 미사일 공격 주장","src":"SAFETY4SEA","date":"2026-08-05","kSum":"예멘의 이란 지원 후티 세력이 홍해 북부 얀부 인근에서 사우디 소유 유조선 Wafa를 탄도미사일로 공격했다고 주장했다. 최근 걸프·홍해를 오가는 유조선을 겨냥한 공격이 다시 확산되는 흐름의 일부다.","eSum":"Yemen's Iran-backed Houthi movement claimed a ballistic-missile strike on the Saudi-owned tanker Wafa in the northern Red Sea off Yanbu, the latest in a renewed wave of attacks on Gulf and Red Sea tanker traffic.","kCause":"무장세력의 의도적 미사일 공격(적대 행위).","eCause":"Deliberate militant missile attack (hostile action).","kLes":"홍해 위협이 얀부 등 북쪽으로 확산되고 있다. 종전에 상대적으로 안전하다고 여겨지던 해역에서도 위협 기반 항로 재설정, UKMTO 보고, 호송·경계 강화를 갱신해야 한다.","eLes":"The Red Sea threat has spread north toward Yanbu; operators must refresh threat-based routing, UKMTO reporting and convoy/watch measures even in areas previously judged lower-risk.","url":"https://safety4sea.com/houthis-claim-new-attack-against-saudi-oil-tanker/"},{"code":"ACC","type":"accident","title":"Indian-flagged cargo vessel MSV Faize Noore Oliya sinks in Red Sea after projectile attack, all crew safe","titleKR":"인도 국적 화물선 MSV Faize Noore Oliya(파이제 누어 올리야), 홍해서 발사체 피격 후 침몰…전원 구조","src":"SAFETY4SEA","date":"2026-08-05","kSum":"인도 국적 상선 MSV Faize Noore Oliya가 8월 4일 오만 연안 홍해 해역에서 발사체 공격을 받은 뒤 침몰했다고 인도 외교부(MEA)가 밝혔다. 승선원 전원은 안전하게 구조됐다.","eSum":"The Indian-flagged commercial vessel MSV Faize Noore Oliya sank in the Red Sea after coming under a projectile attack off the Omani coast on 4 August, according to India's Ministry of External Affairs. All crew were reported safe.","kCause":"발사체(적대 행위)에 의한 선체 손상.","eCause":"Hull damage from a projectile / hostile action.","kLes":"소형 역내 상선까지 표적이 되고 있다. 전원 생존은 신속한 퇴선 준비와 구명설비 대응의 중요성을 보여준다.","eLes":"Even smaller regional traders are now targets; the survival of all crew underlines the value of rapid abandon-ship readiness and effective lifesaving-appliance response.","url":"https://safety4sea.com/indian-cargo-ship-sinks-off-yemen-after-projectile-attack-all-crew-safe/"},{"code":"ACC","type":"accident","title":"Cargo vessel MSS Graphene loses 17 containers overboard off Colombo, Sri Lanka","titleKR":"화물선 MSS Graphene(그래핀), 스리랑카 콜롬보 앞바다서 컨테이너 17개 유실","src":"SAFETY4SEA","date":"2026-08-05","kSum":"몰디브 선적 일반화물선 MV MSS Graphene이 8월 1일 콜롬보항 서쪽 약 17해리 해상에서 악천후를 만나 빈 컨테이너 17개를 유실했다.","eSum":"The Maldives-flagged general cargo vessel MV MSS Graphene lost 17 empty shipping containers overboard on 1 August after encountering rough weather about 17 nautical miles west of the Port of Colombo, Sri Lanka.","kCause":"악천후로 인한 화물 이동·고박 상실(추정).","eCause":"Cargo shift/loss of securing in rough weather (probable).","kLes":"악천후 항해 시 컨테이너 고박 점검, 항로·속력 조정, 유실 컨테이너 신고(2026년 신규 보고 요건)와 항행 위험 경보가 중요하다.","eLes":"Rough-weather passages require verified lashing, route/speed adjustment, and reporting of lost containers (new 2026 requirement) plus navigational hazard warnings.","url":"https://safety4sea.com/several-containers-fall-overboard-off-sri-lanka/"},{"code":"ACC","type":"accident","title":"Drone strike sets Turkish-owned roro Nadezhda ablaze off Novorossiysk, three seriously injured","titleKR":"노보로시스크 앞바다서 터키 소유 로로선 Nadezhda(나데즈다) 드론 피격·화재…3명 중상","src":"Splash247","date":"2026-08-04","kSum":"카메룬 선적·터키 소유 로로선 Nadezhda(IMO 7702657)가 8월 3일 노보로시스크 약 20해리 해상에서 드론에 피격돼 거주구와 선수부가 손상되고 화재가 발생했다. 승선원 22명 중 3명이 중상을 입었고 전원 노보로시스크로 후송됐다.","eSum":"The Cameroon-flagged, Turkish-owned roro Nadezhda (IMO 7702657) was hit by a drone about 20 nm off Novorossiysk on 3 August, damaging the accommodation and bow and starting a fire. Three of the 22 crew were seriously injured and all were evacuated to Novorossiysk.","kCause":"흑해 전쟁 해역에서의 드론 공격. 책임 주체는 확인되지 않았으며 선장은 우크라이나 드론이라고 주장.","eCause":"Drone attack in the Black Sea war zone; no party claimed responsibility, though the master alleged Ukrainian drones.","kLes":"선원 노조는 6~7월 역내에서 15명 이상 선원이 사망했다며 선주들이 위험을 선원에게 전가한다고 비판했다. 전쟁 해역으로의 선원 배치 자체를 재검토해야 한다.","eLes":"A seafarers' union says 15+ seafarers were killed in the region in June-July and accuses owners of chasing freight while crews absorb the risk; strong case for not routing crews into the war zone.","url":"https://splash247.com/three-seriously-injured-as-drone-strikes-turkish-roro-off-novorossiysk/"},{"code":"ACC","type":"accident","title":"Crewmember missing after supramax bulker Minoan Pioneer struck in Strait of Hormuz","titleKR":"호르무즈 해협서 수프라막스 벌커 Minoan Pioneer(미노안 파이오니어) 피격…승선원 1명 실종","src":"Splash247","date":"2026-08-04","kSum":"라이베리아 선적·그리스 운항 수프라막스 벌커 Minoan Pioneer(57,000 dwt)가 8월 3일 밤 호르무즈 해협 카사브 북동 약 20해리 해상에서 미확인 발사체에 기관실을 피격당했다. 전선 정전과 거주구 화재가 이어졌고 3등 기관사가 실종됐다.","eSum":"The Liberian-flagged, Greek-operated supramax bulker Minoan Pioneer (57,000 dwt) was struck in the engine room by an unidentified projectile in the Strait of Hormuz, about 20 nm NE of Khasab, late on 3 August. A full blackout and an accommodation-block fire followed, and the third engineer was reported missing.","kCause":"미확인 발사체 공격(이란 관련 긴장 고조 속). 5일 사이 무산담 반도 인근 4번째 안보 사건.","eCause":"Unclaimed projectile attack amid the Iran conflict; the fourth security incident near Oman's Musandam Peninsula in five days.","kLes":"오만 쪽 호르무즈 항로도 더 이상 안전한 대안이 아니다. 기관실 피격에 따른 정전과 거주구 화재는 이러한 공격의 심각한 인명 피해 잠재력을 보여준다.","eLes":"The Omani side of Hormuz is no longer a safe alternative; engine-room hits causing blackout plus accommodation fire show the severe casualty potential of these strikes.","url":"https://splash247.com/crewmember-missing-after-bulker-struck-in-hormuz/"},{"code":"ACC","type":"accident","title":"MSC sues CargoLoop over electric-vehicle fire that damaged containership cargo","titleKR":"MSC, 전기차 화재로 컨테이너선 화물 손상돼 CargoLoop 상대 소송 제기","src":"Splash247","date":"2026-08-04","kSum":"MSC가 컨테이너에 실린 전기차 화재로 선박 화물이 손상됐다며 물류업체 CargoLoop를 상대로 소송을 제기했다. 컨테이너 화물 운송에서 리튬이온·전기차 화재 위험이 커지고 있음을 보여주는 사례다.","eSum":"MSC has filed suit against logistics firm CargoLoop over an electric-vehicle fire in a container that damaged cargo aboard a containership, underscoring the growing risk of lithium-ion/EV fires in container trades.","kCause":"컨테이너 내 전기차 리튬이온 배터리 화재(추정).","eCause":"Lithium-ion battery fire in a containerized electric vehicle (as alleged).","kLes":"전기차·리튬 화물의 정확한 위험물 신고, 적재·격리, 소화 대비가 컨테이너 화재 예방의 핵심이다.","eLes":"Accurate dangerous-goods declaration, stowage/segregation and firefighting readiness for EV and lithium cargoes are key to preventing container fires.","url":"https://splash247.com/msc-sues-cargoloop-over-electric-vehicle-fire/"},{"code":"ACC","type":"accident","title":"Sweden arrests cargo ship captain over fatal Misje Verde collision with pleasure boat","titleKR":"스웨덴, 소형 보트와 충돌해 2명 사망시킨 화물선 Misje Verde(미셰 베르데) 선장 구속","src":"The Maritime Executive","date":"2026-08-03","kSum":"노르웨이 화물선 Misje Verde(5,300 dwt, 90m)가 7월 28일 스웨덴 서해안 하케피오르드 부근에서 7~8m 모터보트를 추월하다 선미를 들이받았다. 보트는 빨려 들어가 수심 20m에 침몰했고 모녀 2명이 사망했다. 러시아 국적 선장이 구속됐으며 기소는 8월 14일까지 예정이다.","eSum":"The Norwegian cargo ship Misje Verde (5,300 dwt, 90 m) ran down a 7-8 m motorboat from astern while overtaking it near Hakefjord off Sweden's west coast on 28 July. The boat was sucked under and sank in 20 m, killing a mother and daughter. The Russian-national captain was arrested, with an indictment due by 14 August.","kCause":"추정 항행 과실. 검찰은 경계, 추월선의 피항 의무, 속력, 음향신호(발신 안 된 것으로 추정), 선장·도선사 임무 분담을 조사 중.","eCause":"Probable negligent navigation; prosecutors are examining lookout, the overtaking vessel's give-way duty, speed, sound signals (believed none sounded) and master/pilot division of duties.","kLes":"추월선은 지속적 경계를 유지하고 소형 선박에 피항하며 음향신호를 발신해야 한다. 형사 책임이 선장에게 미칠 수 있다.","eLes":"Overtaking vessels must keep a constant lookout, give way to the smaller craft and sound the required signals; criminal liability can attach to the master.","url":"https://maritime-executive.com/article/sweden-arrests-cargo-ship-captain-on-charges-of-causing-collision-death"},{"code":"ACC","type":"accident","title":"Fire aboard Indonesian ferry Mutiara Sentosa 2 leaves five dead and 41 missing","titleKR":"인도네시아 여객선 Mutiara Sentosa 2(무티아라 센토사 2) 화재…5명 사망·41명 실종","src":"The Maritime Executive","date":"2026-08-02","kSum":"1992년 건조된 여객선 Mutiara Sentosa 2가 8월 2일 새벽 마두라섬 인근에서 화재가 발생했으나 당국 신고는 1시간 뒤에야 이뤄졌다. 승선 인원(승무원 약 39명, 승객 232명) 중 220여 명이 인근 선박에 구조됐지만 최소 5명이 사망하고 41명이 실종됐다.","eSum":"A fire broke out before dawn on 2 August aboard the crowded ferry Mutiara Sentosa 2 (built 1992) off Madura Island, but was not reported to authorities until an hour later. Of roughly 39 crew and 232 passengers, 220+ were rescued by nearby vessels; at least five died and 41 remained missing.","kCause":"화재 원인 조사 중. 선령 노후, 과밀 승선, 지연된 경보·신고가 지적됨.","eCause":"Cause under investigation; an aging, overcrowded ship and a delayed alarm/notification are noted concerns.","kLes":"국내 여객선의 화재 탐지, 신속한 조난 신고, 구명설비 적정성이 핵심 교훈이다.","eLes":"Fire detection, prompt distress reporting and adequate lifesaving appliances on domestic passenger ships are the central lessons.","url":"https://maritime-executive.com/article/five-dead-41-missing-in-fire-aboard-indonesian-ferry"},{"code":"ACC","type":"accident","title":"Ukraine sinks Russian-flagged containership Yanina in the Black Sea","titleKR":"우크라이나, 흑해서 러시아 국적 컨테이너선 Yanina(야니나) 격침","src":"The Maritime Executive","date":"2026-08-01","kSum":"7월 31일~8월 1일 밤 우크라이나 드론 2대가 인도발 러시아 국적 컨테이너선 Yanina(Fesco/Rosatom, 2005년 건조, 962 TEU)를 노보로시스크 약 130해리 해상에서 타격해 침몰시켰다. 승선원 17명 중 16명은 터키 소유 컨테이너선 Delphius가, 나머지 1명은 흑해함대 헬기가 구조했다.","eSum":"Two Ukrainian drones struck and sank the Russian-flagged containership Yanina (Fesco/Rosatom; built 2005, 962 TEU) about 130 miles from Novorossiysk overnight on 31 July-1 August. A Turkish-owned containership rescued 16 of 17 crew and a Black Sea Fleet helicopter recovered the 17th.","kCause":"상선을 겨냥한 상호 공격의 확대(드론 공격).","eCause":"Escalating mutual targeting of merchant shipping (drone attack).","kLes":"머스크·하파그로이드가 우크라이나 피더 서비스를 중단하는 등 흑해·아조프해 위험이 급등했다. 양측 모두 상선을 공격하고 있다.","eLes":"Maersk and Hapag-Lloyd suspended Ukraine feeder services as Black Sea/Azov risk surges; both sides are now attacking commercial vessels.","url":"https://maritime-executive.com/article/ukraine-sinks-russian-flagged-containership-in-black-sea-2"}]},{"code":"PSC","kTitle":"항만국통제(PSC)","eTitle":"Port State Control","items":[{"code":"PSC","title":"RiSK4SEA PSI Outlook August 2026: PSC enforcement eases overall but bulkers stay under pressure","titleKR":"RiSK4SEA PSI 아웃룩 2026년 8월: 전반적 PSC 단속 완화되나 벌크선은 압박 지속","src":"SAFETY4SEA","date":"2026-08-05","kSum":"RiSK4SEA의 월간 PSC 스트레스 지수(PSI)는 8월 전 세계 PSC 단속 환경이 뚜렷이 완화됐다고 보고했다. 다만 회복세는 선종별로 갈려 벌크선은 계속 강한 압박을 받고 있다.","eSum":"RiSK4SEA's monthly PSC Stress Index reports a significant easing in the global PSC enforcement climate for August, but recovery is diverging by segment, with bulk carriers remaining under continued pressure.","kImp":"전반적 완화에도 벌커 운항사는 지속적인 표적 점검·억류 위험을 예상해야 하며, 정비·서류·ISM 준비를 느슨히 해서는 안 된다.","eImp":"Even as enforcement softens overall, bulker operators should expect sustained targeting and detention risk and must not relax maintenance, documentation and ISM readiness.","url":"https://safety4sea.com/cm-risk4sea-psi-outlook-august-2026/"},{"code":"PSC","title":"IMO expands global PSC data exchange with Black Sea and Caribbean MoUs","titleKR":"IMO, 흑해·카리브해 MoU와 글로벌 PSC 데이터 교환 확대","src":"SAFETY4SEA","date":"2026-08-05","kSum":"국제해사기구(IMO)가 흑해·카리브해 양해각서(MoU)와 항만국통제(PSC) 데이터 교환 협정을 갱신 체결했다. 선박 검사 정보의 글로벌 공유를 강화하기 위한 조치다.","eSum":"The IMO has signed updated data-exchange agreements with the Black Sea and Caribbean Memoranda of Understanding on Port State Control, aimed at strengthening the global exchange of ship-inspection information.","kImp":"MoU 간 검사·결함·억류 이력 공유가 넓어지면 표적 선정이 정교해지고, 한 지역의 결함 이력이 다른 지역 점검에 반영될 가능성이 커진다.","eImp":"Broader sharing of inspection, deficiency and detention histories across MoUs sharpens targeting and makes a ship's record in one region more likely to follow it into another.","url":"https://safety4sea.com/imo-expands-global-psc-data-exchange-with-black-sea-caribbean-mous/"},{"code":"PSC","title":"Ships urged to prepare for Paris/Tokyo MoU 2026 Concentrated Inspection Campaign on cargo securing","titleKR":"선박, 파리/도쿄 MoU 2026 화물 고박 집중점검(CIC) 대비 촉구","src":"SAFETY4SEA","date":"2026-08-03","kSum":"SQE MARINE가 2026년 화물 고박 집중점검(CIC)을 앞두고 실무 지침을 발표했다. 파리·도쿄 MoU 공동 CIC는 2026년 9월 1일부터 11월 30일까지 시행된다.","eSum":"SQE MARINE has issued best-practice guidance ahead of the 2026 Cargo Securing Concentrated Inspection Campaign. The joint Paris/Tokyo MoU CIC runs from 1 September to 30 November 2026.","kImp":"선박은 화물 고박 매뉴얼(CSM), 고박 장비의 상태·인증, 선원 숙지도에 대한 집중 점검을 받게 되며, 결함 시 억류로 이어질 수 있다.","eImp":"Ships face focused PSC checks on the Cargo Securing Manual, the condition and certification of lashing equipment and crew familiarity, with deficiencies capable of leading to detention.","url":"https://safety4sea.com/cm-complying-with-cic-2026-on-cargo-securing-a-best-practice-guide/"}]},{"code":"PCTC","kTitle":"자동차운반선(PCTC)","eTitle":"Car Carriers (PCTC)","items":[{"code":"PCTC","title":"26-year-old PCTC fetches $42m at auction, highlighting tight vehicle-carrier market","titleKR":"26년 노후 PCTC, 경매서 4,200만 달러 낙찰 - 타이트한 자동차선 시장 방증","src":"Xinde Marine News","date":"2026-08-05","kSum":"선령 26년의 노후 PCTC 한 척이 경매에서 약 4,200만 달러에 낙찰됐다. 노후선치고는 이례적으로 높은 가격으로, 현재 차량 해상운송 시장의 강세를 다시 한 번 보여준다.","eSum":"A 26-year-old PCTC sold for around $42m at auction - an unusually strong price for an ageing vessel and another signal of today's booming vehicle-shipping market.","kImp":"노후선까지 고가에 거래되는 것은 선복 부족의 심각성을 드러낸다.","eImp":"Even ageing tonnage commanding premium prices shows how acute the tonnage shortage has become.","url":"https://www.xindemarinenews.com/news/2081385670380916737"},{"code":"PCTC","title":"MSC makes PCTC newbuilding debut with 12-ship China programme via GCC Global Car Carriers","titleKR":"MSC, GCC 글로벌 카캐리어스 통해 중국 12척 PCTC 신조 프로그램으로 자동차선 진출","src":"Xinde Marine News","date":"2026-08-04","kSum":"MSC의 자동차선 투자 플랫폼 GCC 글로벌 카캐리어스가 중국에서 건조 중인 12척의 대형 LNG 이중연료 PCTC를 선대 리스트에 올렸다. 8,600 CEU 8척과 7,000 CEU 4척으로, 2028~2030년 인도 예정이다.","eSum":"MSC's vehicle-carrier platform GCC Global Car Carriers has listed 12 large LNG dual-fuel PCTCs under construction in China - eight 8,600-CEU and four 7,000-CEU ships - for delivery 2028-2030.","kImp":"세계 최대 컨테이너 선사의 자동차선 본격 진출은 시장 경쟁 구도를 바꿀 잠재력이 있다.","eImp":"The world's largest box carrier moving decisively into car carriers could reshape the sector's competitive landscape.","url":"https://xindemarinenews.com/news/2076467565800202241"},{"code":"PCTC","title":"Atlas Maritime takes delivery of LNG dual-fuel PCTC 'Clean Star' on two-year charter at $80,000/day","titleKR":"아틀라스 마리타임, LNG 이중연료 자동차선 '클린 스타(Clean Star)' 인도 - 2년 용선 일 8만 달러","src":"MarineLink / SAFETY4SEA","date":"2026-08-02","kSum":"아틀라스 마리타임이 8월 2일 중국 CIMC 라플즈 조선소에서 건조한 7,000RT급 LNG 이중연료 자동차운반선(PCTC) '클린 스타'를 인도받았다. 이 선박은 인도 즉시 일당 8만 달러의 2년 정기용선 계약을 확보했다.","eSum":"Atlas Maritime took delivery of the 7,000 RT dual-fuel LNG PCTC 'Clean Star', built at CIMC Raffles in China, on 2 August. The vessel immediately secured a two-year time charter at $80,000 per day.","kImp":"일당 8만 달러의 즉시 용선 확보는 자동차선 시장의 강세와 친환경 신조선에 대한 용선주 선호를 보여준다.","eImp":"An $80,000/day charter fixed on delivery underscores the strength of the car-carrier market and charterer appetite for clean-fuel newbuildings.","url":"https://www.marinelink.com/news/pctc"},{"code":"PCTC","title":"China's vehicle export boom keeps boosting PCTC charter rates, asset values and newbuild orders","titleKR":"중국 자동차 수출 붐, PCTC 용선료·선가·신조 발주 계속 견인","src":"Lloyd's List","date":"2026-08-01","kSum":"중국의 차량 수출 급증이 PCTC 용선료와 자산가치, 신조 발주를 계속 끌어올리고 있다. 6,500 CEU급 1년 정기용선 지수는 연초 대비 약 45% 상승해 일당 약 6만 7천 달러에 이르렀다.","eSum":"China's surging vehicle exports keep lifting PCTC charter rates, asset values and newbuild orders. The 6,500 CEU one-year TC index has climbed about 45% since year-start to around $67,000/day.","kImp":"중국 수출이 세계 자동차선 수급을 좌우하는 핵심 변수임을 재확인시킨다.","eImp":"Confirms Chinese exports as the pivotal driver of global car-carrier supply-demand balance.","url":"https://www.lloydslist.com/LL1157957/Chinas-continued-vehicle-export-boom-boosts-PCTC-charter-rates-asset-values-and-newbuild-orders"},{"code":"PCTC","title":"EUKOR completes first green-methanol bunkering for new Shaper-class car carrier 'Arctic Tern' in Shanghai","titleKR":"유코르, 상하이서 신조 셰이퍼급 자동차선 '아틱 턴(Arctic Tern)' 첫 그린 메탄올 벙커링 완료","src":"gCaptain","date":"2026-07-31","kSum":"유코르 카캐리어스가 운영하는 셰이퍼급 9,300 CEU 자동차선 '아틱 턴'이 상하이에서 첫 그린 메탄올 벙커링을 완료했다. 이 선박은 발레니우스 빌헬름센이 발주한 14척 시리즈의 1번선으로 7월 9일 인도됐다.","eSum":"The 9,300 CEU Shaper-class car carrier 'Arctic Tern', operated by EUKOR, completed its first green-methanol bunkering in Shanghai. It is the first of 14 vessels ordered by Wallenius Wilhelmsen, delivered on 9 July.","kImp":"메탄올 추진 자동차선의 실운항 급유는 자동차 해상운송의 탈탄소 전환을 앞당긴다.","eImp":"Real-world methanol bunkering advances decarbonisation of the vehicle-shipping segment.","url":"https://gcaptain.com/eukor-completes-first-green-methanol-bunkering-for-new-shaper-class-car-carrier-in-shanghai/"},{"code":"PCTC","title":"MOL's car carrier 'Cerulean Ace' certified by ClassNK for enhanced EV fire-fighting measures","titleKR":"MOL 자동차선 '세룰리안 에이스', ClassNK 전기차 화재대응 강화조치(AFVC) 인증 획득","src":"Baird Maritime / ClassNK","date":"2026-07-30","kSum":"미쓰이 O.S.K. 라인스(MOL)의 자동차선 '세룰리안 에이스'가 전기차 운송 중 선내 화재를 방지하는 추가 소방 조치에 대해 ClassNK로부터 'AFVC(Additional Fire-Fighting measures for Vehicle Carrier)' 인증을 받았다.","eSum":"MOL's car carrier 'Cerulean Ace' has been granted ClassNK's 'Additional Fire-Fighting measures for Vehicle Carrier (AFVC)' certification for measures preventing onboard fires during EV transport.","kImp":"전기차 화재 위험 증가에 따라 자동차선 소방 표준 강화가 업계 화두로 부상하고 있다.","eImp":"Rising EV fire risk is pushing enhanced fire-fighting standards to the top of the car-carrier safety agenda.","url":"https://www.marinelink.com/news/car-carriers"}]},{"code":"WW","kTitle":"발레니우스 빌헬름센","eTitle":"Wallenius Wilhelmsen","items":[{"code":"WW","title":"Wallenius Wilhelmsen invites market to Q2 2026 results presentation","titleKR":"발레니우스 빌헬름센(Wallenius Wilhelmsen), 2026년 2분기 실적 발표 안내","src":"Wallenius Wilhelmsen","date":"2026-08-03","kSum":"발레니우스 빌헬름센이 8월 3일 오슬로 증권거래소 공시를 통해 2026년 2분기 실적 발표 일정을 공지했다. 실적은 8월 중순 발표되며 웹캐스트로 생중계될 예정이다. 시장은 중동 리스크와 연료비 상승이 2분기 실적에 미친 영향에 주목하고 있다.","eSum":"Wallenius Wilhelmsen issued a stock-exchange notice on 3 August inviting investors to its Q2 2026 results presentation, to be webcast in mid-August. The market is watching how higher bunker costs and Middle East disruptions weighed on the quarter, against previously guided full-year EBITDA of about USD 1.6bn.","kImp":"2분기 실적은 연료비 급등과 중동 정세가 세계 최대 자동차선사 수익성에 미친 영향을 가늠하는 첫 지표다.","eImp":"Q2 results will be the first read on how fuel-cost spikes and Middle East turmoil hit the world's largest car-carrier operator's margins.","url":"https://www.walleniuswilhelmsen.com/who-we-are/investors/stock-exchange-notices"}]},{"code":"EE","kTitle":"에너지효율·탈탄소","eTitle":"Energy Efficiency","items":[{"code":"EE","title":"27 EU states want IMO Net-Zero Framework to incentivise cleaner fuels early","titleKR":"EU 27개국, IMO 넷제로 프레임워크가 청정연료 조기 인센티브 담아야 (netjero framework)","src":"Ship & Bunker","date":"2026-08-05","kSum":"그리스, 덴마크 등 주요 해운국을 포함한 EU 27개국이 IMO 넷제로 프레임워크(NZF)가 초기 단계부터 청정 마린연료 수요에 대한 장기 확실성을 제공하도록 설계돼야 한다고 촉구했다.","eSum":"The 27 EU member states, including major maritime nations Greece and Denmark, are pushing for the IMO Net-Zero Framework to give long-term demand certainty for cleaner marine fuels from an early stage.","kImp":"IMO NZF 채택을 둘러싼 국가별 입장이 갈리는 가운데, 청정연료 투자 확실성 확보가 탈탄소 속도를 좌우한다.","eImp":"Signals the political battle over the shape of the IMO NZF, whose incentive design will determine how fast clean-fuel investment scales.","url":"https://shipandbunker.com/news/world/328656-27-eu-states-want-imo-nzf-to-incentivise-cleaner-fuels-from-early-stage"},{"code":"EE","title":"Towngas pushes green methanol commercialisation under Hong Kong five-year plan","titleKR":"타운가스, 홍콩 5개년 계획에 그린 메탄올 상용화 촉구 (green methanol sangyonghwa)","src":"Manifold Times","date":"2026-08-05","kSum":"홍콩차이나가스(Towngas)가 홍콩 정부 첫 5개년 계획(2026~2030) 공청회에서 그린 메탄올 벙커링 항만 인프라 확충과 국제 정합적 그린연료 인증체계 도입, 그린 커모디티 거래 메커니즘 신설을 제안했다.","eSum":"Towngas urged the Hong Kong government, in its first Five-Year Plan consultation, to boost green methanol bunkering port facilities, accelerate green methanol commercialisation and build an internationally aligned green-fuel certification system.","kImp":"아시아 벙커링 허브 경쟁에서 홍콩이 그린연료 공급망을 선점하려는 움직임으로, 메탄올 수요 신호를 강화한다.","eImp":"Part of Asia's race to lock in green-fuel supply chains, reinforcing demand signals for methanol as a marine fuel.","url":"https://www.manifoldtimes.com/news/towngas-pushes-for-green-methanol-commercialisation-under-hong-kongs-five-year-plan/"},{"code":"EE","title":"Amon Maritime secures $121.8m financing for two ammonia-fuelled carriers","titleKR":"아몬 머리타임, 암모니아 추진선 2척에 1억2180만 달러 금융 확보 (ammonia chujinseon)","src":"Manifold Times","date":"2026-08-05","kSum":"아몬 머리타임과 내비게이터가스의 합작 Navigator Amon Shipping이 51,350cbm 암모니아 추진 액화암모니아운반선 2척 인도를 위해 ING, 소시에테제네랄, OCBC로부터 1억2180만 달러 금융을 확보했다. 두 선박은 중국 난통에서 건조 중이며 2028년 인도 예정이다.","eSum":"Amon Maritime's JV Navigator Amon Shipping secured a $121.8m facility from ING, Societe Generale and OCBC for two 51,350cbm ammonia-fuelled liquefied ammonia carriers under construction in Nantong, China, due for delivery in 2028.","kImp":"주요 은행들이 암모니아 추진 선박에 금융을 제공한 사례로, 무탄소 연료 프로젝트의 자금 조달 가능성을 입증한다.","eImp":"Bank financing for ammonia-powered ships demonstrates growing lender confidence in zero-carbon fuel projects.","url":"https://www.manifoldtimes.com/news/amon-maritime-announces-usd-121-8-million-financing-for-two-ammonia-fuelled-vessels/"},{"code":"EE","title":"Anew Climate joins SEA-LNG to support liquefied biomethane adoption","titleKR":"Anew Climate, SEA-LNG 합류해 액화 바이오메탄 도입 지원 (aekhwa biomethane)","src":"Manifold Times","date":"2026-08-05","kSum":"미국 환경상품 기업 Anew Climate가 업계 연합 SEA-LNG에 합류해 해운의 액화 바이오메탄(bio-LNG) 도입을 지원한다. 기존 LNG 인프라를 활용해 즉각적인 GHG 감축을 노린다.","eSum":"US environmental-commodities firm Anew Climate has joined the SEA-LNG coalition to support adoption of liquefied biomethane (bio-LNG) in shipping, leveraging existing LNG infrastructure for near-term GHG cuts.","kImp":"기존 LNG 선박·인프라로 바로 쓸 수 있는 bio-LNG 공급망 확대는 단기 탈탄소 실행성을 높인다.","eImp":"Expanding bio-LNG supply that drops into existing LNG assets strengthens the case for a near-term drop-in decarbonisation route.","url":"https://www.manifoldtimes.com/news/anew-climate-joins-sea-lng-to-support-liquefied-biomethane-adoption-in-shipping/"},{"code":"EE","title":"MOL, Hitachi and JAL back Japan's first seawater direct-ocean-capture pilot","titleKR":"MOL·히타치·JAL, 일본 첫 해수 직접포집(DOC) 실증 착수 (haesu jikjeop pojip)","src":"Splash247","date":"2026-08-04","kSum":"MOL, 히타치, 일본항공이 오키나와 구메지마에서 바닷물에 녹아있는 CO2를 직접 분리·포집하는 DOC(Direct Ocean Capture) 실증을 시작하기로 MOU를 체결했다. 육상 컨테이너형 파일럿 설비로 해수를 끌어들여 CO2를 분리하며, 포집 CO2는 합성연료(E-SAF) 원료로 활용을 검토한다.","eSum":"MOL, Hitachi and Japan Airlines signed an MOU to run Japan's first Direct Ocean Capture pilot on Kume Island, using containerised land-based equipment to draw in seawater and separate dissolved CO2, with captured CO2 earmarked as feedstock for synthetic e-fuels such as E-SAF.","kImp":"선박·항공 탈탄소의 핵심인 해양 기반 CO2 제거 기술의 상용화 가능성을 실증하는 초기 단계로, 해운 온실가스 감축 옵션을 넓힌다.","eImp":"An early proof point for ocean-based carbon removal, broadening the toolbox of decarbonisation options for shipping and aviation.","url":"https://splash247.com/mol-backs-japans-first-seawater-carbon-capture-project/"},{"code":"EE","title":"Oil producers Saudi Arabia and UAE call for alternatives to IMO Net-Zero Framework","titleKR":"사우디·UAE, IMO 넷제로 프레임워크 대안 요구 (daean)","src":"Ship & Bunker","date":"2026-08-04","kSum":"산유국인 사우디아라비아와 UAE가 IMO 넷제로 프레임워크가 장거리 무역과 원격 경제에 비용을 과도하게 전가할 수 있다며 대안을 요구하고 나섰다.","eSum":"Oil producers Saudi Arabia and the UAE argue the IMO Net-Zero Framework could disproportionately raise costs for long-haul trade and remote economies, and are calling for alternatives.","kImp":"NZF 최종 채택 전 산유국의 반대가 규제 불확실성을 키워, 연료 전환 로드맵과 투자 판단에 영향을 준다.","eImp":"Producer-state resistance ahead of final NZF adoption adds regulatory uncertainty that weighs on fuel-transition roadmaps and investment.","url":"https://shipandbunker.com/news/emea/615585-oil-producers-saudi-arabia-and-uae-call-for-alternatives-to-imo-nzf"},{"code":"EE","title":"UK Chamber of Shipping publishes industry-first safety evidence base for alternative fuels","titleKR":"영국선주협회, 대체연료 안전 근거 보고서 첫 발간 (daeche yeollyo anjeon)","src":"Manifold Times","date":"2026-08-04","kSum":"영국선주협회가 배터리(BESS), 바이오연료, 메탄올, 수소, 암모니아 등 5개 연료 경로에 대한 예비 고위험 평가를 담은 'Alternative Fuels: Building the Safety Evidence Base' 보고서를 발간했다. 50개 이상 기관 200여 명이 참여했다.","eSum":"The UK Chamber of Shipping released 'Alternative Fuels: Building the Safety Evidence Base', giving preliminary high-level risk assessments across five fuel pathways (battery storage, biofuels, methanol, hydrogen, ammonia), drawing on 200+ participants from 50+ organisations.","kImp":"대체연료 상용화의 최대 병목인 안전·표준·운영 준비를 체계화해 규제와 도입 속도에 실질적 근거를 제공한다.","eImp":"Tackles the safety, standards and operational-readiness bottleneck that gates commercial deployment of alternative fuels.","url":"https://www.manifoldtimes.com/news/uk-chamber-of-shipping-releases-industry-first-safety-evidence-base-for-alternative-bunker-fuels/"},{"code":"EE","title":"CMA CGM names 15,000 TEU methanol-powered boxship ROI ARTHUR","titleKR":"CMA CGM, 15,000TEU 메탄올 추진 컨선 'ROI ARTHUR' 명명 (methanol chujin keonseon)","src":"Manifold Times","date":"2026-08-04","kSum":"CMA CGM이 REX2 서비스에 투입될 15,000TEU 메탄올 추진 컨테이너선 'CMA CGM ROI ARTHUR'를 명명했다. 그룹은 2031년까지 약 200척의 LNG·메탄올 이중연료선을 운항할 계획이다.","eSum":"CMA CGM named its 15,000 TEU methanol-powered containership CMA CGM ROI ARTHUR, joining its REX2 service; the group plans to operate around 200 dual-fuel LNG and methanol ships by 2031.","kImp":"대형 컨테이너 선사의 메탄올 신조선 인도가 이어지며 메탄올 연료 수요와 공급망 형성을 견인한다.","eImp":"Continued methanol newbuild deliveries by a major liner pull methanol fuel demand and supply-chain build-out forward.","url":"https://www.manifoldtimes.com/news/cma-cgm-names-new-15000-teu-methanol-powered-vessel-roi-arthur/"},{"code":"EE","title":"EC clears EUR 103m Dutch funding for renewable methanol and hydrogen ships","titleKR":"EC, 재생 메탄올·수소 추진선에 네덜란드 1억300만 유로 지원 승인 (jaesaeng methanol suso)","src":"Manifold Times","date":"2026-08-03","kSum":"유럽집행위원회(EC)가 재생 메탄올·수소 추진 선박 지원을 위한 네덜란드의 1억300만 유로 규모 국가보조 계획을 승인했다.","eSum":"The European Commission approved a EUR 103m Dutch state-aid scheme to support renewable methanol- and hydrogen-powered ships.","kImp":"공적 자금이 무탄소·재생연료 선박 초기 비용 격차를 메워, 얼리어답터 발주를 촉진한다.","eImp":"Public funding to bridge the cost gap for renewable-fuel vessels helps de-risk early-adopter orders.","url":"https://www.manifoldtimes.com/news/ec-clears-eur-103-mil-dutch-funding-for-renewable-methanol-and-hydrogen-powered-ships/"},{"code":"EE","title":"China pulls ahead of Europe in green shipping fuels","titleKR":"중국, 그린 해운연료 생산에서 유럽 추월 (green haeunyeollyo)","src":"Splash247","date":"2026-07-30","kSum":"중국이 그린 해운연료 프로젝트를 유럽보다 훨씬 빠르게 실제 생산으로 전환하고 있으며, 이미 3개 공장이 그린 메탄올을 생산 중이라고 보도됐다.","eSum":"China is converting green shipping-fuel projects into production far faster than Europe, with three operational Chinese plants already producing green methanol.","kImp":"그린연료 생산 주도권이 중국으로 이동하면 해운 연료 공급망과 가격 경쟁력의 지형이 바뀐다.","eImp":"A shift in green-fuel production leadership toward China reshapes the supply chain and cost competitiveness of marine fuels.","url":"https://splash247.com/china-pulls-ahead-of-europe-in-green-shipping-fuels/"}]},{"code":"DIG","kTitle":"디지털화","eTitle":"Digitalization","items":[{"code":"DIG","title":"Former ZeroNorth boss launches maritime tech advisory","titleKR":"전 제로노스 CEO, 해운 기술 자문사 설립 (gisul jamun)","src":"Splash247","date":"2026-08-05","kSum":"제로노스 전 최고경영자가 해운사의 디지털·AI 전환을 돕는 기술 자문사를 새로 설립했다.","eSum":"A former ZeroNorth chief executive has launched a new maritime technology advisory to help shipping companies with digital and AI transformation.","kImp":"해운 디지털·AI 도입 수요가 커지면서 전문 자문 시장이 형성되고 있음을 보여준다.","eImp":"Reflects an emerging advisory market as demand for maritime digital and AI adoption grows.","url":"https://splash247.com/former-zeronorth-boss-launches-maritime-tech-advisory/"},{"code":"DIG","title":"ZeroNorth launches Propel agentic AI platform with Cargill, Ultrabulk and CMB.TECH","titleKR":"제로노스, 에이전틱 AI 플랫폼 'Propel' 출시 (agentic AI)","src":"Splash247","date":"2026-08-04","kSum":"해운 디지털 최적화 기업 제로노스가 항해 운영용 에이전틱 AI 플랫폼 'Propel'을 출시하고 카길, 울트라벌크, CMB.TECH를 초기 파트너로 확보했다. 반복적 수작업을 대신하고 항해계획 수립·선장 소통·계획 갱신을 자동 수행한다.","eSum":"ZeroNorth launched Propel, an agentic AI platform for voyage operations, with Cargill, Ultrabulk and CMB.TECH as launch partners; it takes over repetitive tasks, generates voyage plans, manages master communication and updates plans continuously.","kImp":"단순 대시보드를 넘어 실제 '행동'하는 AI 에이전트로의 전환을 보여주는 대표 사례로, 상선 운영 자동화 흐름을 가속한다.","eImp":"A flagship example of the shift from dashboards to AI agents that act, accelerating automation of commercial ship operations.","url":"https://splash247.com/cargill-ultrabulk-and-cmb-tech-back-zeronorths-new-ai-platform/"},{"code":"DIG","title":"MarineTraffic brings charts, routes and ETAs onto one map","titleKR":"마린트래픽, 해도·항로·ETA를 단일 지도로 통합 (haedo hangno)","src":"Splash247","date":"2026-08-04","kSum":"선박 추적 플랫폼 마린트래픽이 전자해도, 항로, ETA 등 항해 데이터를 하나의 지도 인터페이스로 통합하는 기능을 선보였다. 분산된 항해·상업 데이터를 단일 화면에서 조회한다.","eSum":"Vessel-tracking platform MarineTraffic unveiled a unified map that brings electronic charts, routes and ETAs into a single interface, consolidating fragmented navigational and commercial data.","kImp":"분절된 데이터 플랫폼 통합은 해운 디지털화의 핵심 과제로, 운영 의사결정 속도와 정확성을 높인다.","eImp":"Consolidating fragmented data platforms is a core digitalisation challenge; unified views speed and sharpen operational decisions.","url":"https://splash247.com/marinetraffic-brings-charts-routes-and-etas-onto-one-map/"},{"code":"DIG","title":"OneLink Performance targets maritime dashboard overload with decision-focused analytics","titleKR":"원링크 퍼포먼스, '대시보드 과부하' 넘어 의사결정형 분석 제시 (uisagyeoljeong)","src":"Splash247","date":"2026-08-04","kSum":"원링크 퍼포먼스가 단순 데이터 표시형 대시보드를 넘어 개입이 필요한 지점과 재무적 성과를 연결하는 3단계 분석 체계를 제시했다. 콜롬비아 그룹의 상시 성능관제센터에서 항로·속도·연료·배출을 모니터링한다.","eSum":"OneLink Performance called for moving beyond data-display dashboards to a three-tier analytics model linking lead indicators, KPIs and commercial outcomes; Columbia Group uses it in its round-the-clock performance control room.","kImp":"센서·노온리포트 등 데이터 폭증 속에서 '더 나은 의사결정'으로의 전환은 성능 관리 SaaS의 방향성을 보여준다.","eImp":"Amid a data flood from sensors and noon reports, the pivot to better decisions marks the direction of vessel-performance software.","url":"https://splash247.com/onelink-performance-takes-aim-at-maritime-dashboard-overload/"},{"code":"DIG","title":"Sedna and PortPal automate port agency emails with AI","titleKR":"Sedna·PortPal, AI로 항만대리점 이메일 업무 자동화 (hangman daerijeom)","src":"Splash247","date":"2026-08-04","kSum":"해운 커뮤니케이션 플랫폼 Sedna가 항만대리점 소프트웨어 PortPal과 연동해 수신 운영 이메일을 구조화된 기항(port call) 워크플로로 전환한다. AI가 첨부·본문에서 정보를 추출해 기항 기록에 자동 반영한다.","eSum":"Communications platform Sedna integrated with port-agency software PortPal to turn incoming operational emails into structured port-call workflows, using AI to extract information from messages and attachments into the port-call record.","kImp":"이메일에 갇힌 항만 대리 업무를 자동화하는 통합 사례로, 해운 소프트웨어 간 연결성 강화 흐름을 보여준다.","eImp":"Automates email-bound port-agency work, illustrating the drive to connect specialist maritime software systems.","url":"https://splash247.com/sedna-and-portpal-automate-port-agency-emails/"},{"code":"DIG","title":"DNV's Piyush Raj on building AI capabilities for maritime professionals","titleKR":"DNV 피유시 라지, 해운 전문가의 AI 역량 구축 방향 제시 (AI yeokryang)","src":"Manifold Times","date":"2026-07-31","kSum":"DNV 머리타임 어드바이저리의 피유시 라지 박사가 해운 AI 환경의 진화와 향후 전문가에게 필요한 역량에 대한 견해를 인터뷰로 밝혔다.","eSum":"DNV Maritime Advisory's Dr. Piyush Raj set out his views on the industry's evolving AI landscape and the skills maritime professionals will need.","kImp":"선급 차원의 AI 역량·교육 논의는 디지털 전환의 인력·거버넌스 측면을 부각한다.","eImp":"A class-society view on AI skills and training highlights the workforce and governance side of digital transformation.","url":"https://www.manifoldtimes.com/news/qa-dnvs-piyush-raj-on-building-ai-capabilities-for-maritime-professionals/"}]},{"code":"TECH","kTitle":"기술·기관","eTitle":"Technical","items":[{"code":"TECH","title":"Explora Journeys names first LNG-powered ship EXPLORA III in Barcelona","titleKR":"엑스플로라 저니스, 첫 LNG 추진선 'EXPLORA III' 바르셀로나서 명명 (LNG chujinseon)","src":"Manifold Times","date":"2026-08-05","kSum":"MSC의 초호화 크루즈 브랜드 엑스플로라 저니스가 바르셀로나에서 자사 첫 LNG 추진 신조선 'EXPLORA III'를 명명했다. 핀칸티에리가 건조했으며 bio-LNG·합성 LNG·바이오연료 사용을 지원하는 설계다.","eSum":"MSC's ultra-luxury brand Explora Journeys named its first LNG-powered newbuild, EXPLORA III, in Barcelona; built by Fincantieri, the ship's LNG capability also supports future bio-LNG, synthetic LNG and biofuels.","kImp":"LNG 추진 신조 크루즈선의 인도·명명은 여객선 부문의 저탄소 추진 채택과 향후 연료 유연성 설계를 보여준다.","eImp":"Delivery and naming of an LNG-powered newbuild cruise ship shows passenger-segment uptake of lower-carbon propulsion and fuel-flexible design.","url":"https://www.manifoldtimes.com/news/explora-journeys-names-first-lng-powered-ship-explora-iii-in-barcelona/"},{"code":"TECH","title":"MITSUI E&S completes FAT of Japan's first WinGD methanol dual-fuel engine","titleKR":"미쓰이 E&S, 일본 첫 WinGD 메탄올 이중연료 엔진 FAT 완료 (methanol enjin FAT)","src":"Manifold Times","date":"2026-08-04","kSum":"미쓰이 E&S가 일본에서 건조된 첫 WinGD 대형 엔진 'DU-WinGD 6X82DF-M-1.0 LP-SCR' 메탄올 이중연료 엔진의 공장수락시험(FAT)을 완료했다. 다마노 공장에서 처음 제작됐으며 국내 선주용 4척 시리즈 1번선에 탑재된다.","eSum":"Mitsui E&S DU completed the Factory Acceptance Test of the DU-WinGD 6X82DF-M-1.0 LP-SCR, the first methanol dual-fuel WinGD large marine engine built in Japan, made at its Tamano Works and destined for the first of a four-ship series for a domestic owner.","kImp":"일본이 정부 조선 재활성화 로드맵 아래 대형 메탄올 엔진 생산 역량을 확보했음을 보여주는 기술 이정표다.","eImp":"A technical milestone showing Japan building local large methanol-engine production capacity under its shipbuilding revitalisation roadmap.","url":"https://www.manifoldtimes.com/news/japans-first-wingd-methanol-dual-fuel-marine-engine-passes-fat-at-mitsui-es/"},{"code":"TECH","title":"Korean Register certifies 3D-printed metal repair process","titleKR":"한국선급(KR), 3D 프린팅 금속 수리 공정 인증 (3D printing geumsok suri)","src":"Splash247","date":"2026-08-04","kSum":"한국선급(KR)이 선박 부품의 3D 프린팅(적층제조) 금속 수리 공정을 인증했다. 현장에서 금속 부품을 적층 방식으로 보수·복원하는 기술의 선급 검증이다.","eSum":"Korean Register (KR) has certified a 3D-printed (additive manufacturing) metal repair process for ship components, providing class validation for on-site additive restoration of metal parts.","kImp":"적층제조 수리의 선급 인증은 예비품 조달·드라이독 정비 방식을 바꿀 잠재력을 갖는 기술적 진전이다.","eImp":"Class certification for additive repair is a technical step with potential to reshape spare-parts sourcing and dry-dock maintenance.","url":"https://splash247.com/kr-certifies-3d-printed-metal-repair-process/"},{"code":"TECH","title":"India's SCI seeks six newbuild LNG containerships in its biggest tender","titleKR":"인도 SCI, 최대 규모 입찰로 LNG 컨선 6척 신조 발주 추진 (LNG keonseon sinjo)","src":"The Maritime Executive","date":"2026-08-04","kSum":"인도 국영 SCI가 7월 31일 회사 사상 최대 규모의 컨테이너선 입찰을 내고 8,000~14,000TEU급 LNG 추진 컨테이너선 최대 6척 신조를 국내외에서 공개 모집했다.","eSum":"India's state-run Shipping Corporation of India released its largest-ever containership tender on July 31, seeking up to six LNG-powered newbuild containerships of 8,000-14,000 TEU, open to domestic and international bidders.","kImp":"대형 LNG 이중연료 신조 발주 흐름을 보여주는 사례로, 조선·엔진 사양과 대체연료 선택 동향을 반영한다.","eImp":"Signals continued large LNG dual-fuel newbuild ordering, reflecting yard, engine-spec and alternative-fuel selection trends.","url":"https://maritime-executive.com/article/india-s-sci-seeks-six-newbuild-lng-containerships-in-its-biggest-tender"},{"code":"TECH","title":"BAR Technologies says IMO move signals pivotal shift for wind propulsion","titleKR":"BAR 테크놀로지스, IMO 조치가 풍력추진 전환점 신호라고 진단 (pungnyeok chujin)","src":"Manifold Times","date":"2026-07-30","kSum":"BAR 테크놀로지스가 IMO의 조치를 풍력추진에 대한 규제상 중대한 전환점으로 평가하며, 해운이 미래연료를 기다리지 말고 지금 즉시 가용한 효율 기술로 탈탄소를 시작해야 한다고 강조했다.","eSum":"BAR Technologies called an IMO move a pivotal regulatory shift for wind propulsion, arguing shipping must stop waiting for future fuels and start decarbonising now with available efficiency technologies.","kImp":"풍력보조추진 등 즉시 적용 가능한 추진 효율 기술의 규제 인정은 신조·개조 설계에서의 채택을 가속한다.","eImp":"Regulatory recognition of ready-now propulsion-efficiency tech such as wind assist accelerates its uptake in newbuild and retrofit design.","url":"https://www.manifoldtimes.com/news/bar-technologies-shipping-must-stop-waiting-for-future-bunker-fuels-to-decarbonise/"}]},{"code":"HR","kTitle":"선원·인사","eTitle":"Marine HR","items":[{"code":"HR","title":"Officer shortage deepens as seafarer demand jumps 35%","titleKR":"선원 수요 5년간 35% 급증하며 사관 부족 심화 (seon-won su-yo 35% geup-jeung)","src":"Seatrade Maritime","date":"2026-08-05","kSum":"2026년 선원 인력 보고서에 따르면 최근 5년간 선원 수요가 35% 늘어 사관 공급이 3만9100명 부족하며, 2030년까지 STCW 자격 사관 11만3735명을 추가 확보해야 한다.","eSum":"The Seafarer Workforce Report 2026 shows seafarer demand rose 35% in five years, leaving a shortfall of 39,100 officers, with 113,735 more STCW-certified officers needed by 2030.","kImp":"사관 부족은 안전운항과 선박관리 비용에 직결되는 구조적 인력 위기다.","eImp":"The officer gap is a structural workforce crisis with direct impacts on safe operations and manning costs.","url":"https://www.seatrade-maritime.com/crewing/officer-shortage-deepens-as-seafarer-demand-jumps-35-"},{"code":"HR","title":"FrontM upgrades OnSHIP app for seafarers and maritime professionals","titleKR":"FrontM, 선원용 OnSHIP 앱 업그레이드 (FrontM, seon-won-yong OnSHIP aep)","src":"Seatrade Maritime","date":"2026-08-05","kSum":"FrontM이 선원과 해운 종사자를 위한 OnSHIP 앱을 개선해 선상 연결성, 복지 서비스, 커뮤니케이션 기능을 강화했다.","eSum":"FrontM has upgraded its OnSHIP app for seafarers and maritime professionals, enhancing onboard connectivity, welfare services and communication tools.","kImp":"연결성은 선원 정신건강과 가족 소통을 지탱하는 핵심 복지 요소다.","eImp":"Connectivity is a core welfare factor sustaining seafarer mental health and family contact.","url":"https://www.seatrade-maritime.com/crewing/frontm-upgrades-onship-app-for-seafarers-and-maritime-professionals"},{"code":"HR","title":"PTC pilots Bigyellowfish health platform across selected fleets","titleKR":"PTC, 일부 선대에 Bigyellowfish 건강 플랫폼 시범 도입 (PTC, geon-gang peul-laet-pom)","src":"Splash247","date":"2026-08-05","kSum":"필리핀 선원관리사 PTC가 선원 정신건강·웰빙을 지원하는 Bigyellowfish 디지털 건강 플랫폼을 선별된 선대에 시범 운영한다.","eSum":"Crew manager PTC is piloting the Bigyellowfish digital health platform across selected fleets to support seafarer mental health and wellbeing.","kImp":"데이터 기반 예방적 건강관리는 선원 복지 향상의 실질적 수단으로 주목받는다.","eImp":"Data-driven preventive healthcare is gaining traction as a practical lever for crew welfare.","url":"https://splash247.com/ptc-pilots-bigyellowfish-health-platform-across-selected-fleets/"},{"code":"HR","title":"Geopolitical strain exposes shipping's crew welfare failings","titleKR":"지정학적 긴장이 드러낸 해운의 선원 복지 실패 (ji-jeong-hak-jeok gin-jang)","src":"Seatrade Maritime","date":"2026-08-03","kSum":"홍해·호르무즈 등 분쟁 해역의 위험이 커지며 선원들이 감내하는 부담이 늘고, 업계 선원 복지 대응 체계의 허점이 드러나고 있다.","eSum":"Rising danger in conflict zones such as the Red Sea and Hormuz is exposing gaps in the industry's crew welfare response as seafarers bear mounting strain.","kImp":"지정학 리스크 상시화로 선원 보호가 복지·인권 이슈의 최전선으로 부상했다.","eImp":"Persistent geopolitical risk has pushed seafarer protection to the forefront of welfare and human-rights concerns.","url":"https://www.seatrade-maritime.com/crewing/geopolitical-strain-exposes-shipping-s-crew-welfare-failings"},{"code":"HR","title":"Seafarers cannot remain the shock absorbers of geopolitical risk","titleKR":"선원이 지정학 리스크의 완충재가 되어선 안 된다 (seon-won, wan-chung-jae)","src":"Seatrade Maritime","date":"2026-08-03","kSum":"선원들이 지정학적 갈등의 위험을 홀로 떠안는 완충재가 되어서는 안 되며, 선주·용선주·국가가 책임을 분담해야 한다는 목소리가 커진다.","eSum":"Commentators argue seafarers must not be left as the 'shock absorbers' of geopolitical conflict, calling for owners, charterers and states to share responsibility.","kImp":"위험 해역 통항 책임 소재와 선원 안전 보장 논의가 본격화되고 있다.","eImp":"It sharpens debate over accountability for high-risk transits and guarantees of seafarer safety.","url":"https://www.seatrade-maritime.com/crewing/seafarers-cannot-remain-the-shock-absorbers-of-geopolitical-risk"},{"code":"HR","title":"Futility is the enemy of everything at sea","titleKR":"무력감이 바다 위 모든 것의 적이다 (mu-ryeok-gam)","src":"Splash247","date":"2026-08-03","kSum":"선원들이 늘어나는 교육·기술·컴플라이언스 부담 속에서도 정작 신체적 안전은 방치된다고 느끼며 업계에 대한 신뢰를 잃고 있다는 문제 제기다.","eSum":"Seafarers are losing faith in an industry that piles on training, technology and compliance while leaving their physical safety neglected, the commentary argues.","kImp":"선원 사기 저하와 이탈은 인력 유지 위기의 근본 원인으로 지목된다.","eImp":"Declining morale and attrition are flagged as root causes of the retention crisis.","url":"https://splash247.com/futility-is-the-enemy-of-everything-at-sea/"},{"code":"HR","title":"Minimum safe manning must not become shipping's commercial target","titleKR":"최소안전정원이 상업적 감축 목표가 되어선 안 된다 (choe-so-an-jeon-jeong-won)","src":"Splash247","date":"2026-07-31","kSum":"피로가 해상 안전의 마지막 방어선을 약화시키는 가운데, 규제상 최소안전정원이 비용 절감을 위한 상업적 목표로 악용돼서는 안 된다는 경고다.","eSum":"With fatigue weakening the last line of defence at sea, the piece warns that regulatory minimum safe manning must not be exploited as a commercial cost-cutting target.","kImp":"정원 축소와 피로 누적은 승무 복지·안전에 직결되는 핵심 인력 이슈다.","eImp":"Crew reductions and fatigue are central manning issues tied directly to welfare and safety.","url":"https://splash247.com/minimum-safe-manning-must-not-become-shippings-commercial-target/"},{"code":"HR","title":"Seafarer happiness falls as 'acute shock' hardens into 'chronic strain'","titleKR":"선원 행복지수 하락, 급성 충격에서 만성 피로로 (seon-won haeng-bok-ji-su ha-rak)","src":"Mission to Seafarers","date":"2026-07-30","kSum":"미션투시퍼러스의 2026년 2분기 선원행복지수가 6.87로 1분기 7.18에서 하락했으며, 제한된 상륙, 과중한 업무, 실질임금 정체가 사기를 갉아먹고 있다.","eSum":"The Mission to Seafarers' Q2 2026 Seafarers Happiness Index fell to 6.87 from 7.18 in Q1, as limited shore leave, excessive workloads and stagnant real wages erode morale.","kImp":"행복지수 하락은 인력 유지·안전·평판과 직결되는 선원 복지의 종합 지표다.","eImp":"The falling index is a composite welfare gauge tied to retention, safety and reputation.","url":"https://www.missiontoseafarers.org/news/seafarer-happiness-falls-as-acute-shock-hardens-into-chronic-strain"},{"code":"HR","title":"Abandoned and unpaid: seafarers left stranded, owed $68,000 in Las Palmas","titleKR":"라스팔마스서 임금 6.8만달러 체불·유기된 선원들 (im-geum che-bul, yu-gi)","src":"ITF","date":"2026-07-30","kSum":"ITF에 따르면 라스팔마스에서 선원 6명이 6만8000달러의 임금을 받지 못한 채 유기됐으며, 일부는 2024년부터 승선해 2026년 1월 이후 무급 상태였다.","eSum":"The ITF reports six seafarers abandoned in Las Palmas owed $68,000 in unpaid wages, with some aboard since 2024 and unpaid since January 2026.","kImp":"2026년 선원 유기가 사상 최악 수준으로 늘며 임금 체불이 심각한 인권 이슈로 부상했다.","eImp":"With 2026 abandonment cases at record highs, unpaid wages have become an acute human-rights issue.","url":"https://www.itfglobal.org/en/news/abandoned-and-unpaid-seafarers-left-stranded-owed-68000-in-las-palmas"}]},{"code":"HSEQ","kTitle":"HSEQ","eTitle":"HSEQ","items":[{"code":"HSEQ","title":"CHIRP lessons learned: safe polar navigation requires multiple independent sources, not one recorded track","titleKR":"CHIRP 교훈: 극지 항해 안전은 하나의 기록 항적이 아닌 복수의 독립 정보원에 달려 있다","src":"SAFETY4SEA","date":"2026-08-05","kSum":"CHIRP Maritime의 니어미스 보고서에 따르면, 한 탐험 크루즈선이 사전 계획 항로나 대체 항로 없이 두꺼워지는 유빙(6~7/10 밀집도)을 뚫고 개방수역으로 향했다. 1등 항해사는 여러 빙산이 식별되지 않았던 앞선 선박의 전자 항적을 그대로 따르려 했고, 당직사관의 시각 관측은 충분히 활용되지 않았다.","eSum":"A CHIRP Maritime near-miss report describes an expedition cruise vessel pushing toward open water through thickening ice (6-7/10 concentration) with no pre-planned or contingency route. The Chief Officer pushed to follow a previous vessel's recorded electronic track - along which several icebergs had gone unidentified - while the OOW's visual observations were under-used.","kImp":"역사적 항적에 대한 과신은 허위 안전감을 준다. 그롤러는 레이더로 탐지되지 않을 수 있어 직접 육안 관측이 1차 방어선이며, 불확실성이 커지면 대체 항로와 감속이 필요하다. 상업·일정 압박이 항해 안전을 앞서서는 안 된다.","eImp":"Over-reliance on historical tracks gives a false sense of security; growlers can be undetectable by radar, so direct visual observation is a primary defence, and passage plans need alternative routes and speed reductions when uncertainty rises - commercial pressure must never override navigational safety.","url":"https://safety4sea.com/lessons-learned-in-polar-waters-safe-navigation-requires-multiple-sources/"},{"code":"HSEQ","title":"CHIRP lessons learned: weakened safety barriers and incomplete maintenance nearly cause an engine-room fire","titleKR":"CHIRP 교훈: 약화된 안전 방벽과 미완의 정비가 기관실 화재로 이어질 뻔","src":"SAFETY4SEA","date":"2026-08-04","kSum":"CHIRP Maritime는 한 선박에서 약화된 안전 방벽과 완료되지 않은 정비가 기관실 화재로 번질 뻔한 사례에서 교훈을 정리했다. 결함 신호가 방치되면 방어층이 하나씩 무력화된다는 점을 강조한다.","eSum":"CHIRP Maritime draws lessons from a report in which a vessel's weakened safety barriers and incomplete maintenance contributed to a near engine-room fire, stressing how unattended warning signs erode successive layers of defence.","kImp":"결함·이상 상태는 주의를 요구하는 안전 신호다. 정비 완결성, 안전 방벽 유지, 이상 징후에 대한 즉각 대응이 기관실 화재 예방의 핵심이다.","eImp":"A deficiency or abnormal condition is a safety signal requiring attention; maintenance completeness, intact safety barriers and prompt response to warning signs are central to preventing engine-room fires.","url":"https://safety4sea.com/lessons-learned-an-condition-is-a-safety-signal-that-requires-attention/"},{"code":"HSEQ","title":"Managing the risks of lithium-ion battery fires in the marine environment","titleKR":"해양 환경에서 리튬이온 배터리 화재 리스크 관리","src":"MarineLink","date":"2026-08-03","kSum":"MarineLink/EFI Global 분석은 하이브리드·전기 추진, 자동차운반선의 전기차, 선내 에너지저장장치(ESS), 승무원 기기 등에서 비롯되는 해양 리튬이온 배터리 화재를 다룬다. 열폭주는 자기지속적이며 밀폐 공간에서 극심한 열과 가연성 가스를 발생시켜 선박·화물의 전손으로 이어지는 경우가 많다.","eSum":"A MarineLink/EFI Global analysis addresses lithium-ion battery fires in the marine space - from hybrid/electric propulsion and EVs on car carriers to onboard energy-storage systems and crew devices. Thermal runaway is self-sustaining, produces extreme heat and flammable gases in confined spaces, and often causes total loss of vessel or cargo.","kImp":"화재 원인은 셀 손상, 부적절한 충전, 내부 결함 등이다. 초기에 화재 현장을 증거로 보존하고, 화재 패턴 분석을 넘어선 다학제적 조사, 책임 당사자 조기 특정, 구상권 전략 수립이 중요하다.","eImp":"Fires stem from cell damage, improper charging or internal defects; early preservation of the fire scene, multidisciplinary investigation beyond fire-pattern analysis, early identification of responsible parties and a subrogation strategy are all critical.","url":"https://www.marinelink.com/news/managing-risks-batteryrelated-marine-541723"}]},{"code":"KR","kTitle":"한국해운","eTitle":"Korean Shipping","items":[{"code":"KR","title":"Taiwan's Yang Ming orders six 13,000 TEU LNG-fuelled boxships from Hanwha Ocean","titleKR":"대만 양밍해운, 한화오션에 1.3만TEU급 LNG추진 컨선 6척 발주","src":"코리아쉬핑가제트","date":"2026-08-05","kSum":"대만 선사 양밍해운이 7월16일 이사회에서 한화오션에 1만3000TEU급 LNG 연료 추진 컨테이너선 6척을 발주하는 안건을 승인했다. 신조 가격은 총 11억1000만달러 규모다. 이번 발주로 한화오션은 대형 LNG 이중연료 컨테이너선 수주잔고를 추가로 확보하게 됐다.","eSum":"Taiwan's Yang Ming approved at a July 16 board meeting an order for six 13,000 TEU LNG dual-fuel container ships at Hanwha Ocean, worth about $1.11bn in total. The deal adds sizeable large LNG-fuelled boxship tonnage to Hanwha Ocean's orderbook.","kImp":"한화오션이 대만 선사로부터 대형 친환경 컨선 물량을 따내며 상선 부문 수주 회복 흐름을 보여준다.","eImp":"A win from a Taiwanese liner shows Hanwha Ocean rebuilding momentum in commercial-ship orders for eco boxships.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147747"},{"code":"KR","title":"Korean Register briefs Southeast Asia on carbon rules and supply-chain sanctions risk","titleKR":"한국선급, 싱가포르서 탄소규제·공급망 위기 소개","src":"코리아쉬핑가제트","date":"2026-08-05","kSum":"한국선급(KR)은 7월29~30일 싱가포르에서 동남아시아 해사업계를 대상으로 KR 동남아시아 위원회 및 기술세미나를 열고 국제사회의 탄소 규제와 국제 제재에 따른 공급망 위기 상황을 공유했다. 29일 열린 기술세미나에는 지역 선사·기자재·항만 관계자 등이 참석했다.","eSum":"Korean Register held its Southeast Asia Committee meeting and a technical seminar in Singapore on July 29-30, briefing regional maritime players on international carbon regulations and supply-chain risks arising from global sanctions. The July 29 seminar drew local owners, equipment makers and port officials.","kImp":"한국 선급이 동남아 시장에서 탄소·제재 규제 대응 역량을 알리며 글로벌 클래스 영향력 확대를 꾀한다.","eImp":"KR is extending its global class footprint by positioning itself on decarbonization and sanctions compliance in Southeast Asia.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147767"},{"code":"KR","title":"Government floats merging four port authorities, drawing sharp criticism","titleKR":"정부, 4개 항만공사 통합안 부상…'졸속 행정' 비판","src":"코리아쉬핑가제트","date":"2026-08-05","kSum":"최근 정부가 부산·인천·울산·광양 등 전국 4개 항만공사(PA)를 하나로 통합하려는 방안을 검토하고 있다. 효율성 제고와 규모의 경제를 명분으로 내세우지만, 업계는 이를 지방분권에 역행하는 시대착오적 중앙집권적 발상이자 항만 물류의 근간을 흔드는 졸속 행정이라고 강하게 비판했다.","eSum":"The government is weighing a plan to merge Korea's four port authorities (Busan, Incheon, Ulsan, Gwangyang) into one, citing efficiency and economies of scale. Industry voices sharply criticize the idea as a regressive, centralizing move that runs against decentralization and could undermine the foundations of the country's port logistics.","kImp":"부산 등 핵심 항만 거버넌스 개편은 국내 항만 운영·투자 구조에 중대한 영향을 미칠 수 있는 정책 이슈다.","eImp":"Restructuring governance of key ports like Busan is a policy issue with major implications for domestic port operations and investment.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147746"},{"code":"KR","title":"Samsung Heavy wins 2 crude tankers, hitting 2026 commercial-ship target early","titleKR":"삼성중공업, 원유운반선 2척 수주…상선부문 수주목표 조기 달성","src":"코리아쉬핑가제트","date":"2026-08-04","kSum":"삼성중공업이 유럽 지역 선사로부터 원유운반선 2척을 2680억원에 수주했다고 3일 공시했다. 이 선박은 2029년 8월까지 인도될 예정이다. 이번 수주로 삼성중공업은 올해 상선 부문 수주 목표를 조기에 달성했다.","eSum":"Samsung Heavy Industries disclosed on Aug 3 an order for two crude oil tankers worth 268bn won from a European owner, for delivery by August 2029. The deal lets the yard reach its 2026 commercial-ship order target ahead of schedule.","kImp":"빅3 조선소가 상선 목표를 연중 조기 달성하며 한국 조선업의 견조한 수주 사이클을 재확인시킨다.","eImp":"A Big Three yard reaching its commercial target early reaffirms the strength of Korea's shipbuilding order cycle.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147751"},{"code":"KR","title":"9 in 10 Korean exporters see profits squeezed by rising logistics costs","titleKR":"수출기업 10곳 중 9곳, 물류비 상승에 수익 악화","src":"코리아쉬핑가제트","date":"2026-08-04","kSum":"한국무역협회 조사 결과 중동 전쟁 여파로 국제유가와 해상운임이 급등하면서 국내 수출기업의 물류비 부담이 급격히 커진 것으로 나타났다. 수출기업 3곳 중 1곳은 지난해보다 물류비와 원가가 올랐지만 인상분을 수출가격에 반영하지 못하고 전액 자체 부담한 것으로 조사됐다.","eSum":"A Korea International Trade Association survey found soaring oil prices and ocean freight, stemming from Middle East conflict, have sharply raised logistics costs for Korean exporters. One in three could not pass higher freight and input costs into export prices, absorbing them entirely.","kImp":"운임·유가 급등이 한국 수출 경쟁력과 화주-선사 관계에 실질적 압박을 주고 있음을 보여준다.","eImp":"Highlights how freight and fuel spikes are squeezing Korean export competitiveness and shipper-carrier dynamics.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147743"},{"code":"KR","title":"Pan Ocean seen posting 668bn won annual operating profit as ex-SK Shipping VLCCs delivered","titleKR":"팬오션, 연간 영업이익 6680억원 전망…SK해운서 인수한 VLCC 10척 순차 인도","src":"쉬핑뉴스넷","date":"2026-08-03","kSum":"하나증권은 팬오션의 2026년 연간 영업이익을 전년比 36% 늘어난 6680억원으로 상향했다. 2분기 매출은 48% 증가한 1조9137억원, 영업이익은 57% 증가한 1937억원으로 컨센서스를 크게 상회했다. 벌크(영업이익 847억원, +60%)와 탱커(437억원, +166%)가 실적을 견인했다. SK해운에서 인수한 VLCC 10척이 순차 인도되며 하반기 이익에 기여하고, VLCC 모멘텀은 계약 갱신이 시작되는 2028년 이후 본격화될 전망이다.","eSum":"Hana Securities lifted Pan Ocean's 2026 operating profit forecast to 668bn won, up 36% y/y. Q2 revenue rose 48% to 1.914tn won and operating profit jumped 57% to 193.7bn won, well above consensus, led by bulk (+60%) and tankers (+166%). Ten VLCCs bought from SK Shipping are being delivered in phases; the bigger VLCC upside is expected from 2028 as charters roll over.","kImp":"한국 최대 벌크선사가 전쟁발 운임 강세와 탱커·에너지 선대 확장으로 실적 체력을 키우고 있음을 보여준다.","eImp":"Shows Korea's largest bulk carrier building earnings power on war-driven freight strength and an expanding tanker/energy fleet.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=71431"},{"code":"KR","title":"Daehan Shipbuilding wins 2 suezmax tankers from Turkey's Ditas Shipping","titleKR":"대한조선, 튀르키예 디타스쉬핑서 수에즈막스 탱커 2척 수주","src":"쉬핑뉴스넷","date":"2026-08-03","kSum":"대한조선이 튀르키예 디타스쉬핑(Ditas Shipping)으로부터 15만7000DWT급 원유 수에즈막스 탱커 2척을 수주했다. 디타스가 수에즈막스를 발주한 것은 2016년 HD현대중공업 발주 이후 10년 만이다. 2029년 12월 인도 예정으로 척당 신조선가는 9230만달러로 클락슨 벤치마크(8950만달러)를 웃돌았다. 대한조선은 올해 수에즈막스 누적 17척을 수주했으며, 2026년 누적 수주액은 약 2.25조원으로 연간 목표의 1.6배를 달성했다.","eSum":"Daehan Shipbuilding booked two 157k-DWT suezmax crude tankers from Turkey's Ditas Shipping, the owner's first suezmax order in a decade. Priced at $92.3m each (above the $89.5m Clarksons benchmark) for December 2029 delivery. Daehan has now won 17 suezmaxes this year and its 2026 order intake of about 2.25tn won is 1.6x its annual target.","kImp":"중견 조선소 대한조선의 수에즈막스 독보적 수주세는 한국 탱커 건조 경쟁력과 도크 여력 소진을 보여준다.","eImp":"Daehan's dominant suezmax run underscores Korean tanker-building competitiveness and a fast-filling orderbook at mid-tier yards.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=71432"},{"code":"KR","title":"HMM plans additional 5.5tn won investment in 2030 container fleet, expanding to 166 ships","titleKR":"HMM, 2030년 컨테이너 선대에 5.5조원 추가 투자…선대 166척으로 확대","src":"쉬핑뉴스넷","date":"2026-08-01","kSum":"HMM은 7월24일 공시를 통해 2030년 컨테이너 선대계획과 관련해 5.5조원 규모의 추가 신규 투자 계획(총액 29조원)을 발표했다. 2030년 총 선복량은 147만TEU로 2024년 발표치(155만TEU)보다 줄었으나 선박 수는 종전 130척에서 166척으로 늘었다. 허브앤스포크 트렌드에 대응해 중소형 피더선을 적극 확보하려는 움직임으로 해석된다. LS증권은 HMM의 2분기 영업이익이 4706억원(전년比 +102%)으로 컨센서스를 웃돌 것으로 전망했다.","eSum":"In a July 24 filing HMM unveiled an extra 5.5tn won of investment (total 29tn won) tied to its 2030 container fleet plan. Total capacity drops to 1.47m TEU (from the 1.55m TEU projected in 2024) but the ship count rises to 166 from 130, reflecting a push to secure mid- and small feeders for a hub-and-spoke network. LS Securities sees Q2 operating profit at 470.6bn won, up 102% y/y and above consensus.","kImp":"국적 1위 컨테이너 선사의 대규모 투자 방향이 피더·중소형선 중심으로 재편되면서 향후 국내 조선소 발주와 노선 전략에 영향을 준다.","eImp":"The scale and feeder-oriented shift of Korea's top container carrier shapes future domestic newbuilding orders and network strategy.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=71426"},{"code":"KR","title":"KOMERI runs Korea's first land-based hybrid propulsion test for mid-size ships","titleKR":"조선기자재연구원, 국내 최초 중형선박 하이브리드 추진 육상실증","src":"코리아쉬핑가제트","date":"2026-07-31","kSum":"한국조선해양기자재연구원(KOMERI)은 7월31일 경남 양산 친환경추진본부 친환경선박 하이브리드추진 육상실증센터에서 축발전전동기(SGM)를 적용한 중형 선박 동력시스템 통합 성능평가 설비의 시운전을 시작했다. 국내 최초로 중형선박용 하이브리드 추진시스템을 육상에서 통합 실증하는 설비다.","eSum":"The Korea Marine Equipment Research Institute (KOMERI) began commissioning an integrated power-system test facility for mid-size ships using a shaft generator-motor (SGM) at its eco-ship hybrid propulsion land test center in Yangsan on July 31. It is Korea's first land-based integrated demonstration of a hybrid propulsion system for mid-size vessels.","kImp":"국산 친환경 추진 기자재의 실증 인프라 구축은 한국 조선·기자재 업계의 탈탄소 경쟁력 강화로 이어진다.","eImp":"Building demonstration infrastructure for domestic green propulsion equipment strengthens Korea's decarbonization edge in shipbuilding and marine equipment.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147742"}]},{"code":"INS","kTitle":"선체보험(H&M)","eTitle":"Hull & Machinery Insurance","items":[{"code":"INS","title":"Another vessel struck on Omani side of Strait of Hormuz, keeping hull war-risk premiums elevated","titleKR":"호르무즈 해협 오만 측에서 또 다른 선박 피격, 선체 전쟁위험(H&M) 보험료 고공행진 지속","src":"Insurance Marine News","date":"2026-08-05","kSum":"8월 3~4일 밤 UKMTO는 호르무즈 해협 통항 중 선박 인근에서 폭발이 관측된 새로운 사건을 보고했다. 이란-미국 긴장 국면에서 선박 피격이 이어지며 해당 수역의 선체·전쟁위험 담보 조건이 계속 경색되고 있다.","eSum":"UKMTO reported a fresh incident overnight 3-4 August in which a master observed an explosion in close proximity to his ship while transiting Hormuz. Repeated strikes are keeping hull and war-risk cover in the region under pressure.","kImp":"선체보험(H&M) 및 전쟁위험 인수사는 호르무즈 통항 선박에 대한 추가보험료(AP)와 담보 배제 구역을 재조정하게 되며, 선주 비용 부담이 커진다.","eImp":"Hull and war-risk underwriters must keep repricing additional premiums and breach areas for Hormuz transits, raising owners' insurance costs.","url":"https://insurancemarinenews.com/insurance-marine-news/another-ship-struck-on-omani-side-of-hormuz/"},{"code":"INS","title":"Six Saudi VLCCs turn back from Gulf of Aden and reroute via Cape of Good Hope","titleKR":"사우디 VLCC 6척, 아덴만서 회항해 희망봉 우회 (전쟁위험 회피 항로 재편)","src":"Insurance Marine News","date":"2026-08-05","kSum":"사우디 선적 VLCC 6척이 최근 며칠 사이 아덴만에서 항로를 바꿔 남아프리카 방향으로 우회하고 있다. 전쟁위험 노출을 피하기 위한 항로 재편이 확산되고 있다.","eSum":"Six Saudi-flagged VLCCs changed course in the Gulf of Aden within the past few days and are now routing around southern Africa to avoid war-risk exposure.","kImp":"전쟁위험 담보 구역 회피는 항해 거리·기간을 늘려 선체·기관 마모 및 운항 리스크 프로파일을 바꾸고, H&M·전쟁위험 인수 판단에 직접 반영된다.","eImp":"Rerouting to dodge war-risk breach areas lengthens voyages and alters vessels' operational risk profiles, feeding directly into hull and war-risk underwriting.","url":"https://insurancemarinenews.com/insurance-marine-news/six-saudi-tankers-turn-back-from-gulf-of-aden-head-for-cape-of-good-hope/"},{"code":"INS","title":"GasLog says LNG carrier Gaslog Shanghai 'stable' after Strait of Hormuz incident","titleKR":"GasLog, 호르무즈 사고 후 LNG선 'Gaslog Shanghai' 안정 상태 확인 (가스로그 상하이)","src":"Insurance Marine News","date":"2026-08-04","kSum":"LNG운반선 Gaslog Shanghai(IMO 9600528)가 호르무즈 해협을 빠져나오던 중 발생한 사고 이후 안정 상태이며 승선원 전원이 안전한 것으로 확인됐다.","eSum":"LNG carrier Gaslog Shanghai (IMO 9600528) is stable after an incident on exiting the Strait of Hormuz, with all crew safe and accounted for.","kImp":"고가 LNG선의 선체 손상 가능성은 H&M 보험자에게 대형 클레임 리스크를 의미하며, 사고 원인·손상 정도에 따라 선체·기관 담보 정산 규모가 결정된다.","eImp":"Potential damage to a high-value LNG carrier is a significant H&M claims exposure; the cause and extent of damage will drive any hull and machinery settlement.","url":"https://insurancemarinenews.com/insurance-marine-news/gaslog-says-its-lng-tanker-gaslog-shanghai-is-stable-after-soh-incident/"},{"code":"INS","title":"RoRo cargo ship Nadezhda struck by drones near Novorossiysk","titleKR":"RoRo 화물선 'Nadezhda', 노보로시스크 인근서 드론 피격 (나데즈다호)","src":"Insurance Marine News","date":"2026-08-04","kSum":"터키발 러시아행 청과물을 실은 RoRo 화물선 Nadezhda(IMO 7702657)가 8월 3일 노보로시스크 항 30마일 해상에서 드론 공격을 받았다.","eSum":"RoRo cargo ship Nadezhda (IMO 7702657), carrying fresh produce from Turkiye to Russia, was struck by drones on 3 August about 30 miles off Novorossiysk.","kImp":"흑해 상선에 대한 드론 공격은 선체 전손·부분손 클레임을 촉발하고, 흑해·아조프해 전쟁위험 요율과 담보 가능성에 압박을 준다.","eImp":"Drone strikes on merchant ships trigger hull total/partial-loss claims and pressure war-risk rates and availability across the Black Sea and Azov basins.","url":"https://insurancemarinenews.com/insurance-marine-news/cargo-ship-hit-near-novorossiysk/"},{"code":"INS","title":"Russian naphtha Suezmax Sea Icon aborts Bab al-Mandab passage, reroutes around Africa","titleKR":"러시아 나프타 적재 Suezmax 'Sea Icon', 바브엘만데브 통항 취소하고 아프리카 우회","src":"Insurance Marine News","date":"2026-08-04","kSum":"파나마 선적 Suezmax Sea Icon(IMO 9806615)이 러시아산 나프타를 싣고 홍해 남단 바브엘만데브 해협 통항을 중단하고 아프리카 우회로를 택했다. 주말 동안 사우디 원유 적재 탱커 2척도 홍해를 이탈했다.","eSum":"Panama-flagged Suezmax Sea Icon (IMO 9806615) with Russian naphtha aborted its Bab al-Mandab transit and rerouted around Africa; two Saudi-crude tankers also exited the Red Sea over the weekend.","kImp":"홍해 회피 항로 확산은 전쟁위험 담보 수요·요율과 선체 운항 리스크 산정에 지속적으로 영향을 미친다.","eImp":"Spreading Red Sea avoidance continues to shape war-risk demand and rating and hull operational-risk assessments.","url":"https://insurancemarinenews.com/insurance-marine-news/russian-cargo-tanker-reroutes-around-africa-two-tankers-with-saudi-oil-exit-red-sea-over-weekend/"},{"code":"INS","title":"Russia steps up protection of Black Sea cargo ships and develops alternative routes","titleKR":"러시아, 흑해 화물선 보호 강화 및 대체 항로 개발 (전쟁위험 완화 노력)","src":"Insurance Marine News","date":"2026-08-04","kSum":"러시아 교통부 장관은 8월 3일 아조프-흑해 분지 내 선박 보호를 강화하고 대체 항로를 개발 중이라고 밝혔다.","eSum":"Russia's transport minister said on 3 August the ministry is stepping up protection of ships in the Azov-Black Sea basin and developing alternative routes.","kImp":"국가 차원의 호송·보호 조치는 흑해 전쟁위험 인수 심사의 핵심 변수로, 선체·전쟁위험 요율 및 담보 조건 완화 여부에 영향을 준다.","eImp":"State-level convoy and protection measures are a key input to Black Sea war-risk underwriting, affecting whether hull and war-risk terms can ease.","url":"https://insurancemarinenews.com/insurance-marine-news/russia-increases-protection-of-black-sea-cargo-ships-develops-alternative-routes/"},{"code":"INS","title":"UKMTO reports two tanker incidents off Oman, one struck by unknown object","titleKR":"UKMTO, 오만 해역서 탱커 사고 2건 보고 (1척 미상 물체에 피격)","src":"Insurance Marine News","date":"2026-08-03","kSum":"UKMTO는 8월 1일 오만 해역에서 탱커 1척이 미상의 물체에 피격되는 등 2건의 해상 사고를 보고했다.","eSum":"UKMTO on 1 August reported two maritime incidents off Oman, including a tanker struck by an unknown object.","kImp":"탱커 피격은 선체 물적 손상 클레임과 함께 해당 수역 전쟁위험 추가보험료 상향의 근거가 된다.","eImp":"Tanker strikes generate hull physical-damage claims and justify higher war-risk additional premiums for the area.","url":"https://insurancemarinenews.com/insurance-marine-news/ukmto-reports-two-tanker-incidents-off-oman/"},{"code":"INS","title":"Container ship CNC Uranus runs aground after striking buoy entering Chittagong","titleKR":"컨테이너선 'CNC Uranus', 치타공 입항 중 부표 충돌 후 좌초 (H&M 좌초 클레임)","src":"Insurance Marine News","date":"2026-08-03","kSum":"컨테이너선 CNC Uranus(IMO 9760627)가 8월 3일 방글라데시 치타공 항 입항 중 부표를 들이받고 좌초했다. 인명 피해나 오염은 보고되지 않았다.","eSum":"Container ship CNC Uranus (IMO 9760627) ran aground on 3 August after striking a buoy while entering Chittagong, Bangladesh; no injuries or pollution reported.","kImp":"좌초는 전형적인 선체·기관(H&M) 담보 사고로, 선저 손상 검사·수리 비용과 구조·이초 비용이 보험 정산 대상이 된다.","eImp":"Grounding is a classic hull and machinery casualty; bottom-damage survey, repair and refloating costs fall to H&M cover.","url":"https://insurancemarinenews.com/insurance-marine-news/marine-round-up-5th-august-2026/"}]},{"code":"PNI","kTitle":"P&I 클럽","eTitle":"P&I Clubs","items":[{"code":"PNI","title":"Steamship Mutual issues notice of cancellation for owned hull war risks (Circular L.485)","titleKR":"Steamship Mutual, 소유 선체 전쟁위험 담보 해지 통지 발행 (회람 L.485)","src":"Steamship Mutual","date":"2026-08-03","kSum":"Steamship Mutual이 소유 선체 전쟁위험(Owned Hull War Risks)에 대한 해지 통지 회람(L.485)을 발행했다. 이는 지정 전쟁위험 담보를 7일 통지로 재조정하는 표준 조치로, 변동성이 큰 전쟁위험 구역 재설정의 일환이다.","eSum":"Steamship Mutual has issued Circular L.485, a notice of cancellation for owned hull war risks, the standard seven-day mechanism used to reset war-risk cover amid volatile conflict zones.","kImp":"해지 통지 후 재조건화(재요율·구역 재설정)는 회원 선주의 전쟁위험 부보 비용과 담보 범위에 직접 영향을 미친다.","eImp":"Cancel-and-rewrite of war-risk cover directly affects members' war-risk premiums and the scope of protection.","url":"https://www.steamshipmutual.com/l485-owned-hull-war-risks-notice-cancellation"},{"code":"PNI","title":"International Group confirms pooling arrangements now cover autonomous vessels (MASS)","titleKR":"국제그룹(IG), 자율운항선(MASS)까지 풀링 담보 확대 확인 (완전 무인선 포함)","src":"International Group of P&I Clubs","date":"2026-07-31","kSum":"국제 P&I 그룹은 IMO MASS 코드 채택에 이어, 완전 무인선을 포함한 모든 자율화 단계의 자율운항선(MASS) 배상책임을 그룹 풀링 약정으로 담보할 수 있음을 확인했다. 담보 가능성은 개별 클럽 인수 심사와 기국·선급 요건 준수에 따른다.","eSum":"The International Group has confirmed that MASS liabilities across all levels of autonomy, including fully unmanned ships, are now eligible for Group pooling, subject to individual club underwriting and flag/class compliance.","kImp":"자율운항선에 대한 상호 P&I 고한도 담보 제공은 신기술 선박의 보험 공백을 메워 자율운항 상용화를 뒷받침하는 중대한 진전이다.","eImp":"Extending mutual P&I high-limit cover to autonomous ships closes a key insurance gap and underpins commercialisation of MASS.","url":"https://www.igpandi.org/article/international-group-confirms-pooling-arrangements-for-autonomous-vessels/"},{"code":"PNI","title":"Steamship Mutual circular on EU 21st sanctions package against Russia (L.484)","titleKR":"Steamship Mutual, EU 대러 21차 제재 패키지 회람 발행 (L.484)","src":"Steamship Mutual","date":"2026-07-31","kSum":"Steamship Mutual이 EU의 대러시아 21차 제재 패키지 내용을 정리한 회원 회람(L.484)을 발행했다. 유가상한제·그림자선단·거래 제한 관련 회원 준수 지침을 담고 있다.","eSum":"Steamship Mutual has issued member Circular L.484 summarising the EU's 21st sanctions package against Russia, with compliance guidance on price-cap, shadow-fleet and trading restrictions.","kImp":"제재 패키지 갱신은 P&I 담보 유효성과 직결되며, 회원 선주는 위반 시 담보 상실 위험이 있어 즉각적 준수 검토가 필요하다.","eImp":"Each sanctions update bears directly on P&I cover validity; members risk loss of cover for breaches and must review compliance immediately.","url":"https://www.steamshipmutual.com/l484-eu-sanctions-21st-sanctions-package-against-russia"},{"code":"PNI","title":"NorthStandard becomes first P&I club to join the Dry Bulk Centre of Excellence","titleKR":"NorthStandard, P&I 클럽 최초로 '드라이벌크 우수센터(DBCE)' 가입 (노스스탠다드)","src":"Dry Bulk (Palladian)","date":"2026-07-30","kSum":"NorthStandard가 P&I 클럽 최초로 드라이벌크 우수센터(DBCE)에 가입해, 벌크 부문과의 손해예방·모범사례 공유 협력을 강화한다고 밝혔다. 그리스 손해예방 디렉터 John Southam이 참여 의의를 설명했다.","eSum":"NorthStandard has become the first P&I club to join the Dry Bulk Centre of Excellence (DBCE), deepening loss-prevention and best-practice collaboration with the dry bulk sector, per Loss Prevention Director John Southam.","kImp":"대형 IG 클럽이 벌크 전문 협의체에 직접 참여하는 것은 손해예방 데이터·전문성 결합을 통해 회원 리스크 관리와 클레임 저감으로 이어질 수 있다.","eImp":"A major IG club embedding itself in a dry-bulk body signals a push to combine loss-prevention data and expertise to reduce member risk and claims.","url":"https://www.drybulkmagazine.com/dry-bulk/30072026/northstandard-joins-the-dry-bulk-centre-of-excellence/"},{"code":"PNI","title":"IG/Steamship circular on safe carriage of nickel ore cargoes in the south-western Pacific (L.483)","titleKR":"IG·Steamship, 남서태평양 니켈광 화물 안전운송 회람 발행 (L.483)","src":"Steamship Mutual / International Group","date":"2026-07-30","kSum":"국제그룹이 INTERCARGO 및 Roxburgh와 공동 작성한 회람(Steamship L.483)으로, 남서태평양 지역 니켈광 수출과 관련한 액상화 위험 등 과제를 짚고 회원 리스크 완화 권고를 제시했다.","eSum":"An International Group circular (Steamship L.483), prepared with INTERCARGO and Roxburgh, highlights the liquefaction and related risks of nickel ore exports from the south-western Pacific and gives members risk-mitigation recommendations.","kImp":"니켈광 액상화는 벌커 전복·전손 등 대형 P&I 클레임의 대표 원인으로, 사전 예방 지침은 인명·선체 손실 방지에 핵심적이다.","eImp":"Nickel-ore liquefaction is a leading cause of catastrophic bulker losses and P&I claims; preventive guidance is central to avoiding loss of life and vessels.","url":"https://www.steamshipmutual.com/l483-safe-carriage-nickel-ore-cargoes-south-western-pacific-ocean"}]},{"code":"CLASS","kTitle":"선급","eTitle":"Classification","items":[{"code":"CLASS","title":"DNV publishes official Port State Control CIC 2026 questionnaire on cargo securing","titleKR":"DNV, 2026 항만국통제(PSC) 집중점검(CIC) 공식 질문지 공개 (화물 고박 주제)","src":"DNV","date":"2026-08-04","kSum":"DNV는 Paris·Tokyo MOU가 9월 1일부터 시행하는 화물 고박(Cargo Securing) 관련 집중점검(CIC)에 대비해 공식 질문지가 공개됐다고 안내했다. 선사·선박은 점검 항목에 맞춰 사전 준비가 필요하다.","eSum":"DNV has flagged that the official questionnaire for the Paris and Tokyo MoU joint Concentrated Inspection Campaign (CIC) on Cargo Securing, starting 1 September, is now published, and set out preparation guidance for operators.","kImp":"선급의 CIC 대비 지침은 선박 억류·결함 지적 리스크를 줄이는 실무 기준으로, 화물 고박 관리체계 점검의 기준점이 된다.","eImp":"Class guidance ahead of the CIC is a practical benchmark for reducing detention and deficiency risk and for reviewing cargo-securing management.","url":"https://www.dnv.com/news/2026/port-state-control-cic-2026-official-questionnaire-now-published/"},{"code":"CLASS","title":"ABS and Samsung Heavy Industries advance 50 MW and 200 MW floating data centre designs with AiP","titleKR":"ABS·삼성중공업, 50MW·200MW 부유식 데이터센터 설계 진전 및 기본승인(AiP) 획득","src":"ABS","date":"2026-08-04","kSum":"ABS와 삼성중공업이 50MW·200MW급 부유식 데이터센터 설계를 공동 개발하고 설계승인 계약과 기본승인(AiP)을 체결했다. 이는 신설된 한미 조선 파트너십 센터(KUSPC)의 첫 성과 중 하나다.","eSum":"ABS and Samsung Heavy Industries have advanced 50 MW and 200 MW floating data centre designs, signing a design approval agreement and securing AiP, among the first outcomes of the new Korea-U.S. Shipbuilding Partnership Center.","kImp":"부유식 데이터센터는 선급 규정이 미비한 신흥 해양 자산으로, 선급의 기본승인은 상업화의 규제·안전 기준을 선도적으로 제시한다.","eImp":"Floating data centres are an emerging offshore asset class lacking mature rules; class AiP sets pioneering safety and regulatory benchmarks for commercialisation.","url":"https://pressreleases.eagle.org/news/abs-and-samsung-heavy-industries-advance-50-mw-and-200-mw-floating-data-center-designs"},{"code":"CLASS","title":"LR and Argentine Naval Prefecture strengthen technical cooperation to enhance navigation safety","titleKR":"LR·아르헨티나 해군경비대, 항행 안전 강화 위한 기술협력 확대 (로이드선급)","src":"Lloyd's Register","date":"2026-07-30","kSum":"Lloyd's Register(LR)와 아르헨티나 해군경비대(Prefectura Naval)가 항행 안전 제고를 위한 기술협력을 강화하기로 했다. 선급 전문성과 기국·해상당국 감독을 연계하는 협력이다.","eSum":"Lloyd's Register and the Argentine Naval Prefecture have agreed to strengthen technical cooperation to enhance navigation safety, linking class expertise with flag/coastal-authority oversight.","kImp":"선급-해상당국 간 기술협력은 지역 선대의 안전 기준과 검사 체계를 정합화해 결함·사고 저감에 기여한다.","eImp":"Class-authority technical cooperation aligns regional fleet safety standards and inspection regimes, helping cut deficiencies and casualties.","url":"https://www.lr.org/en/knowledge/press-room/"}]},{"code":"COMM","kTitle":"상업·시황","eTitle":"Commercial & Markets","items":[{"code":"COMM","title":"Goldenport lifts ultramax newbuild bet","titleKR":"골든포트(Goldenport), 울트라막스 신조 발주 두 배로 확대","src":"Splash247","date":"2026-08-05","kSum":"그리스 선주 골든포트가 중국 난퉁샹위 조선소에 울트라막스 벌커 신조를 2척 추가해 발주 규모를 두 배로 늘렸다. 2029년 인도 예정으로, 벌크선 시황 개선 기대를 반영한 투자다.","eSum":"Greek owner Goldenport has doubled its ultramax newbuilding programme at China's Nantong Xiangyu, adding two more bulkers for 2029 delivery. The order reflects confidence in a firming dry bulk market.","kImp":"벌크선 신조 발주가 시황 회복 기대 속에 이어지고 있음을 보여준다.","eImp":"It signals continued bulker ordering on optimism over the dry cargo market.","url":"https://splash247.com/goldenport-lifts-ultramax-newbuild-bet/"},{"code":"COMM","title":"Greece's Nautilus makes tanker newbuild debut at Wuhu","titleKR":"그리스 노틸러스(Nautilus), 우후(Wuhu)조선소서 첫 탱커 신조 발주","src":"Splash247","date":"2026-08-05","kSum":"그리스 선주 노틸러스매니지먼트가 중국 우후조선소에 MR1급 석유·화학운반선 최대 2척을 발주하며 탱커 신조시장에 데뷔했다. 강세인 프로덕트 탱커 시황을 겨냥한 진입이다.","eSum":"Greek owner Nautilus Management has entered the tanker newbuilding market with an order for up to two MR1 product and chemical carriers at China's Wuhu Shipyard. The debut targets a strong product tanker market.","kImp":"탄탄한 프로덕트 탱커 시황이 신규 선주들의 진입을 끌어들이고 있음을 보여준다.","eImp":"It shows a robust product tanker market drawing fresh owners into newbuilding.","url":"https://splash247.com/greeces-nautilus-makes-tanker-newbuild-debut-at-wuhu/"},{"code":"COMM","title":"Global bauxite trade triples in a decade","titleKR":"글로벌 보크사이트(bauxite) 교역, 10년 새 3배로 급증","src":"Splash247","date":"2026-08-05","kSum":"지난 10년간 세계 보크사이트 해상 물동량이 세 배로 늘며 케이프사이즈·벌커 톤마일 수요를 지지하고 있다. 기니 등 서아프리카발 장거리 물동량이 벌크선 시장의 새로운 성장 동력으로 부상했다.","eSum":"Global seaborne bauxite trade has tripled over the past decade, underpinning capesize and bulker tonne-mile demand. Long-haul cargoes from West Africa, notably Guinea, have become a key growth driver for the dry bulk market.","kImp":"보크사이트 장거리 물동량 확대가 벌크선 수요의 구조적 지지 요인이 되고 있음을 보여준다.","eImp":"It highlights bauxite long-haul flows as a structural support for dry bulk demand.","url":"https://splash247.com/global-bauxite-trade-triples-in-a-decade/"},{"code":"COMM","title":"Polaris Shipping orders four ore carriers at Beihai Shipbuilding","titleKR":"폴라리스쉬핑(Polaris Shipping), 베이하이(Beihai)조선소에 광석운반선 4척 발주","src":"Seatrade Maritime","date":"2026-08-05","kSum":"한국 폴라리스쉬핑이 중국 베이하이조선소에 대형 광석운반선(ore carrier) 4척을 발주했다. 장기 철광석 운송계약 대응과 선대 확충을 위한 투자로 풀이된다.","eSum":"South Korea's Polaris Shipping has ordered four large ore carriers at China's Beihai Shipbuilding. The newbuildings are aimed at supporting long-term iron ore contracts and expanding its dry bulk fleet.","kImp":"장기 철광석 물동량 기대가 대형 벌커 발주로 이어지고 있음을 보여준다.","eImp":"It reflects long-term iron ore demand translating into large bulker orders.","url":"https://www.seatrade-maritime.com/dry-bulk/polaris-shipping-orders-four-ore-carriers-at-beihai-shipbuilding"},{"code":"COMM","title":"ONE trebles full-year profit forecast","titleKR":"ONE(오션네트워크익스프레스), 연간 순익 전망 3배로 상향","src":"Seatrade Maritime","date":"2026-08-04","kSum":"일본계 컨테이너 선사 ONE이 견조한 운임과 물동량에 힘입어 연간 이익 전망을 세 배로 상향했다. 지정학 불안이 선복을 묶어두며 주요 항로 운임이 높게 유지된 것이 실적을 끌어올렸다.","eSum":"Container line ONE has trebled its full-year profit forecast on the back of resilient freight rates and volumes. Geopolitical disruption has tied up capacity and kept rates elevated across major trades, boosting earnings.","kImp":"컨테이너 선사들의 실적이 시장 침체 우려를 뒤엎고 강세를 이어가고 있음을 보여준다.","eImp":"It shows container carriers' earnings defying earlier gloom as rates stay firm.","url":"https://www.seatrade-maritime.com/containers/one-trebles-full-year-profit-forecast"},{"code":"COMM","title":"CMB.TECH books massive profit from VLCC sale","titleKR":"CMB.TECH, VLCC 매각으로 대규모 차익 실현","src":"Seatrade Maritime","date":"2026-08-04","kSum":"벨기에 CMB.TECH가 초대형원유운반선(VLCC)을 매각해 큰 차익을 남겼다. 사상 최고 수준의 탱커 선가와 강한 운임 환경 속에서 자산가치가 급등한 결과다.","eSum":"Belgium's CMB.TECH has booked a large profit from selling a VLCC, capitalising on decade-high tanker asset values. The sale reflects surging secondhand prices amid an exceptionally strong crude tanker market.","kImp":"탱커 선가와 운임이 동반 급등하며 선주들의 자산매각 차익이 커지고 있음을 보여준다.","eImp":"It underlines how soaring tanker values and rates are handing owners big S&P gains.","url":"https://www.seatrade-maritime.com/tankers/cmb-tech-books-massive-profit-from-vlcc-sale"},{"code":"COMM","title":"Chinese EV boom fuels demand and charter rates for car-carriers","titleKR":"중국 전기차 붐, 자동차운반선(PCTC) 수요·용선료 다시 견인","src":"The Loadstar","date":"2026-08-03","kSum":"중국 전기차 수출 급증으로 최신 자동차운반선(PCTC) 용선료가 다시 하루 10만 달러 선에 접근하고 있다. 신조선 '레이크 로토루아(Lake Rotorua)'는 SAIC안지에 하루 9만 달러, 노후선조차 3만~4만 달러대에 고정될 만큼 선복이 타이트하다. 상반기 중국 차량 수출은 약 510만 대로 65% 급증했다.","eSum":"Modern PCTC charter rates are approaching $100,000/day again, driven by surging Chinese EV exports. Newbuild Lake Rotorua fixed to SAIC Anji at $90,000/day, while even older units command $40,000, reflecting tight tonnage. China exported nearly 5.1m vehicles in H1, up 65% year on year.","kImp":"PCTC 용선시장이 2022년 이후 최고 수준으로 재차 과열되고 있음을 보여준다.","eImp":"It shows the car-carrier charter market re-tightening toward its post-2022 highs.","url":"https://theloadstar.com/chinese-ev-boom-fuels-demand-and-charter-rates-for-car-carriers/"},{"code":"COMM","title":"Shippers unimpressed by container line reliability","titleKR":"화주들, 컨테이너 선사 정시성(신뢰도)에 불만","src":"Seatrade Maritime","date":"2026-08-03","kSum":"화주들이 컨테이너 선사들의 스케줄 신뢰도에 여전히 불만을 나타내고 있다. 홍해 우회와 항로 재편으로 정시 도착률이 낮아진 가운데 운임은 높게 유지되며 화주 부담이 커지고 있다.","eSum":"Shippers remain unimpressed with container lines' schedule reliability. Red Sea diversions and network reshuffling have kept on-time performance low even as freight rates stay elevated, raising costs for cargo owners.","kImp":"운임 강세에도 서비스 품질 저하로 화주-선사 간 긴장이 지속되고 있음을 보여준다.","eImp":"It shows persistent shipper-carrier tension as service quality lags despite high rates.","url":"https://www.seatrade-maritime.com/containers/shippers-unimpressed-by-container-line-reliability"},{"code":"COMM","title":"Atlas Maritime and EMF clinch 'record-high' charter deal for last PCTC","titleKR":"아틀라스(Atlas)·EMF, 마지막 PCTC '클린스타(Clean Star)' 사상 최고 용선료로 고정","src":"Shipping Telegraph","date":"2026-07-30","kSum":"그리스 아틀라스마리타임과 EMF가 LNG 이중연료 PCTC '클린스타'를 중국 대형 운영사에 2년, 하루 8만 달러에 용선했다. EMF는 자사 선대 사상 최고 용선료라고 밝혔으며 총 5,600만 달러 매출이 예상된다.","eSum":"Atlas Maritime and EMF have fixed their dual-fuel LNG PCTC Clean Star to a leading Chinese operator for two years at $80,000/day. EMF calls it the highest time-charter rate ever achieved across its fleet, expected to generate about $56m in gross revenue.","kImp":"친환경 신조 PCTC가 프리미엄 용선료를 이끌어내는 시장 강세를 확인시킨다.","eImp":"It confirms premium charter rates for eco newbuild car carriers in a strong market.","url":"https://shippingtelegraph.com/freight-news/atlas-maritime-and-emf-clinch-record-high-charter-deal-for-last-pctc/"},{"code":"COMM","title":"Sallaum Lines returns to China Merchants yard for car carriers","titleKR":"살라움라인(Sallaum Lines), 자오상쥐(China Merchants) 조선소에 PCTC 추가 발주","src":"Seatrade Maritime","date":"2026-07-30","kSum":"살라움라인이 자오상쥐(China Merchants) 조선소에 8,600CEU급 LNG 이중연료·암모니아 레디 PCTC 1+1척을 발주했다. 이는 샤먼조선 2척 계약에 이은 것으로, 살라움의 신조 프로그램은 총 9척으로 늘었다.","eSum":"Sallaum Lines has ordered one-plus-one 8,600 ceu LNG dual-fuel, ammonia-ready PCTCs at China Merchants, the largest ships in its fleet. It follows a two-ship deal at Xiamen, bringing Sallaum's newbuilding programme to nine vessels.","kImp":"PCTC 선사들이 대형·친환경 신조로 선대 확장을 이어가는 발주 랠리를 보여준다.","eImp":"It illustrates the ongoing PCTC newbuilding rush toward larger, cleaner tonnage.","url":"https://www.seatrade-maritime.com/maritime-transportation/sallaum-lines-returns-to-china-merchants-yard-for-car-carriers"}]},{"code":"GEO","kTitle":"지정학","eTitle":"Geopolitics","items":[{"code":"GEO","title":"Global shipping unites against Hormuz tolls","titleKR":"글로벌 해운업계, 호르무즈 통항료 부과 방안에 공동 반대","src":"Seatrade Maritime","date":"2026-08-05","kSum":"국제 해운업계가 호르무즈해협 통항에 요금을 부과하려는 움직임에 한목소리로 반대하고 나섰다. 자유항행 원칙을 훼손하고 물류비를 끌어올릴 수 있다는 우려에서다.","eSum":"The global shipping industry has united against proposals to impose tolls on transits through the Strait of Hormuz. Industry bodies warn such charges would undermine freedom of navigation and raise trade costs.","kImp":"핵심 해상 요충지에 대한 통항료 부과가 자유항행 원칙을 둘러싼 새 갈등으로 번지고 있음을 보여준다.","eImp":"It shows a brewing clash over freedom of navigation as tolls are floated for a key chokepoint.","url":"https://www.seatrade-maritime.com/regulations/global-shipping-unites-against-hormuz-tolls"},{"code":"GEO","title":"Black Sea attacks choke grain, coal and iron ore trades","titleKR":"흑해 공격 격화, 곡물·석탄·철광석 교역 마비","src":"Splash247","date":"2026-08-05","kSum":"러시아가 미콜라이우·오데사 인근에서 선박 4척과 항만시설을 공격했다고 주장하는 등 흑해가 세계에서 가장 위험한 상선 해역이 됐다. 7월 러시아 흑해·아조프항 더티탱커 선적은 62% 급감했고 곡물·석탄·철광석 물동량도 사실상 정지됐다.","eSum":"Russia claimed strikes on four vessels and port infrastructure near Mykolaiv and Odesa as the Black Sea becomes the most dangerous environment for commercial shipping. Russian Black Sea dirty tanker loadings fell 62% in late July, with grain, coal and iron ore flows near a standstill.","kImp":"흑해 분쟁 격화가 탱커·벌커 물동량과 곡물 공급망에 광범위한 충격을 주고 있음을 보여준다.","eImp":"It shows the intensifying Black Sea conflict hitting tanker and bulker flows and global grain supply.","url":"https://splash247.com/black-sea-attacks-choke-grain-coal-and-iron-ore-trades/"},{"code":"GEO","title":"Drone attacks slash Black Sea tanker loadings","titleKR":"드론 공격으로 흑해 탱커 선적량 급감","src":"Seatrade Maritime","date":"2026-08-05","kSum":"흑해 선박·항만에 대한 드론 공격이 잇따르며 러시아 흑해발 탱커 선적량이 급감했다. 전쟁위험 보험료가 치솟고 있으며, BIMCO는 사태 지속 시 세계 더티탱커 선적이 3% 줄 수 있다고 경고했다.","eSum":"A wave of drone attacks on Black Sea vessels and ports has slashed Russian tanker loadings. War-risk premiums are surging, and BIMCO warns that, if sustained, the disruption could cut global dirty tanker loadings by 3%.","kImp":"흑해 드론전이 탱커 시장과 원유 물류에 실질적 공급 충격을 주고 있음을 보여준다.","eImp":"It shows Black Sea drone warfare delivering a real supply shock to the tanker market.","url":"https://www.seatrade-maritime.com/security/drone-attacks-slash-black-sea-tanker-loadings"},{"code":"GEO","title":"Indian cargo vessel sinks after apparent attack near Yemen","titleKR":"인도 화물선, 예멘 인근서 피격 후 침몰","src":"gCaptain","date":"2026-08-04","kSum":"인도 국적 화물선 '파이제 누레 올리야(Faize Noore Oliya)'가 8월 4일 예멘 호데이다 남쪽 홍해에서 폭발물 적재 보트로 추정되는 공격을 받고 전복·침몰했다. 인도 국민 13명 포함 승선원 14명은 예멘 해경에 전원 구조됐다.","eSum":"An Indian-flagged cargo vessel, Faize Noore Oliya, capsized and sank in the Red Sea on August 4 after being struck by an apparent explosives-laden boat south of Hodeidah. All 14 crew, including 13 Indians, were rescued by the Yemeni Coast Guard.","kImp":"후티의 해상 공격이 소형 상선까지 확대되며 홍해 위험이 재고조되고 있음을 보여준다.","eImp":"It shows Houthi-linked attacks spreading to smaller merchant ships, re-escalating Red Sea risk.","url":"https://gcaptain.com/indian-cargo-vessel-sinks-after-apparent-attack-near-yemen/"},{"code":"GEO","title":"Cargo ship hit by projectile in Strait of Hormuz, one crew member missing","titleKR":"호르무즈해협서 화물선 피격, 선원 1명 실종","src":"gCaptain","date":"2026-08-04","kSum":"8월 3일 밤 오만 영해를 북상하던 화물선이 미상의 발사체에 기관실·거주구를 맞아 화재·전원상실로 표류했다. 선원 1명이 실종됐으며, 앞선 8월 2일 두 척의 탱커도 '세파 해군'을 자처한 위협을 받았다.","eSum":"A cargo ship transiting Omani waters in the Strait of Hormuz was struck by an unknown projectile late on August 3, hit in its engine room and accommodation, sparking a fire and knocking out power. One crew member is missing; JMIC keeps the strait at a SEVERE threat rating.","kImp":"호르무즈 통항이 급감한 가운데 IRGC 관련 위협이 상선 안전을 지속 위협하고 있음을 보여준다.","eImp":"It underscores persistent IRGC-linked threats to merchant safety as Hormuz transits stay far below normal.","url":"https://gcaptain.com/cargo-ship-hit-by-projectile-in-strait-of-hormuz-one-crew-member-missing/"},{"code":"GEO","title":"EU warship boards another sanctioned Russian shadow fleet tanker in Mediterranean","titleKR":"EU 군함, 지중해서 제재 대상 러시아 그림자함대 탱커 또 검문·승선","src":"gCaptain","date":"2026-08-03","kSum":"EU 이리니(IRINI) 작전 소속 이탈리아 해군 기함이 8월 2일 판텔레리아 서쪽 공해에서 제재 대상 탱커 '토아파요(Toa Payoh)'를 국적확인 명목으로 검문·승선했다. 2주 새 두 번째 조치로, EU는 러시아 그림자함대 단속을 강화하고 있다.","eSum":"An EU Operation IRINI flagship boarded the sanctioned tanker Toa Payoh in international waters west of Pantelleria on August 2 for a flag-verification inspection. It was the second such boarding in two weeks as the EU intensifies enforcement against Russia's shadow fleet.","kImp":"EU가 제재 회피 유조선에 대한 실효적 해상 단속을 강화하고 있음을 보여준다.","eImp":"It signals the EU escalating at-sea enforcement against sanctions-evading tankers.","url":"https://gcaptain.com/eu-warship-boards-another-sanctioned-russian-shadow-fleet-tanker-in-mediterranean/"},{"code":"GEO","title":"Russia assembles unprecedented Arctic oil convoy to bypass shipping hotspots","titleKR":"러시아, 분쟁 해역 우회 위해 사상 최대 북극 원유 선단 구축","src":"gCaptain","date":"2026-08-03","kSum":"러시아가 북극해항로(NSR)를 통해 아시아로 원유 수출을 가속하며 사상 최대 규모의 유조선 선단을 집결시켰다. 이미 약 800만 배럴이 이동 중이거나 진입 대기 중으로, 이는 작년 항해시즌 전체 물량의 절반을 넘는다.","eSum":"Russia has assembled an unprecedented tanker fleet in the Arctic to accelerate crude exports to Asia via the Northern Sea Route. Vessels carrying roughly 8m barrels are already transiting or waiting to enter the ice-covered lane, more than half of last year's entire season.","kImp":"러시아가 제재·분쟁 해역을 우회하려 북극항로 의존을 빠르게 키우고 있음을 보여준다.","eImp":"It shows Russia rapidly leaning on the Arctic route to bypass sanctions and conflict chokepoints.","url":"https://gcaptain.com/russia-assembles-unprecedented-arctic-oil-convoy-to-bypass-global-shipping-hotspots/"},{"code":"GEO","title":"Six Saudi tankers turn away from Gulf of Aden, ship-tracking data shows","titleKR":"사우디 탱커 6척, 아덴만서 뱃머리 돌려…선박추적 데이터 확인","src":"gCaptain","date":"2026-08-03","kSum":"사우디 국적 초대형 유조선 6척이 최근 아덴만에서 항로를 바꿔 남아프리카로 향한 것이 선박추적 데이터로 확인됐다. 후티의 사우디 선박 겨냥 위협에 따른 회피 항해다.","eSum":"Six Saudi-flagged supertankers changed course in the Gulf of Aden and are heading to southern Africa, tracking data showed, after Houthi threats to target Saudi shipping. The diversions confirm a broad rerouting away from the Red Sea.","kImp":"후티 위협이 사우디 대형 선단 전반의 항로 이탈을 촉발하고 있음을 보여준다.","eImp":"It confirms Houthi threats are driving a fleet-wide rerouting of Saudi tankers.","url":"https://gcaptain.com/six-saudi-tankers-turn-away-from-gulf-of-aden-ship-tracking-data-shows/"},{"code":"GEO","title":"Two tankers with Saudi oil exit Red Sea over weekend","titleKR":"사우디 원유 실은 탱커 2척, 주말 사이 홍해 통과","src":"gCaptain","date":"2026-08-02","kSum":"사우디 원유를 실은 탱커 2척이 주말 사이 바브엘만데브 해협을 통과한 반면 호르무즈해협 통항은 둔화됐다. 후티의 사우디 항만 겨냥 위협 속에서도 일부 화물은 여전히 홍해를 오가고 있다.","eSum":"Two tankers laden with Saudi oil crossed the Bab el-Mandeb strait over the weekend, while traffic through the Strait of Hormuz slowed. Some cargoes continue to transit the Red Sea despite Houthi threats against Saudi-linked shipping.","kImp":"홍해·호르무즈 양대 요충지의 물동량이 위협 수위에 따라 요동치고 있음을 보여준다.","eImp":"It illustrates how flows through both Red Sea and Hormuz chokepoints swing with the threat level.","url":"https://gcaptain.com/two-tankers-with-saudi-oil-exit-red-sea-over-weekend/"},{"code":"GEO","title":"Saudi ships shun Red Sea chokepoint for rare Africa journey","titleKR":"사우디 유조선들, 홍해 요충지 피해 이례적 아프리카 우회","src":"gCaptain","date":"2026-07-31","kSum":"후티 위협 속에 사우디 국영 바흐리(Bahri) 소속 VLCC 6척이 바브엘만데브 해협을 피해 아프리카 남단을 도는 이례적 항로를 택했다. 우회로 항해 기간이 최소 2주 늘어난다.","eSum":"Six Saudi VLCCs owned by state carrier Bahri are diverting away from Bab el-Mandeb and sailing around Africa amid Houthi threats. The rerouting adds at least two weeks to their voyages, with some crude now shipped via Egypt's Sidi Kerir.","kImp":"후티의 사우디 항만 봉쇄 위협이 원유 물류와 항로를 근본적으로 뒤흔들고 있음을 보여준다.","eImp":"It shows the Houthi blockade threat upending Saudi crude logistics and trade routes.","url":"https://gcaptain.com/saudi-ships-shun-red-sea-chokepoint-for-rare-africa-journey/"}]},{"code":"TW","kTitle":"트레이드윈즈 헤드라인","eTitle":"TradeWinds Headlines","items":[{"code":"TW","title":"US military disables second vessel in enforcement of Hormuz blockade","titleKR":"美 군, 호르무즈 봉쇄 집행 중 두 번째 선박 무력화","src":"TradeWinds","date":"2026-08-04","kSum":"미국 군이 호르무즈 해협 봉쇄 집행 과정에서 두 번째 선박을 무력화했다. 이란산 원유 수출을 차단하려는 미국의 봉쇄 작전이 계속되고 있음을 보여준다.","eSum":"The US military has disabled a second vessel in enforcing its Strait of Hormuz blockade, underscoring the ongoing campaign to choke Iranian oil exports.","kImp":"미군의 실력행사 확대로 호르무즈 통항 리스크와 전쟁위험보험료가 더욱 높아지고 있다.","eImp":"Expanding US enforcement further elevates Hormuz transit risk and war-risk premiums.","url":"https://www.tradewindsnews.com/tankers/us-military-disables-second-vessel-in-enforcement-of-hormuz-blockade/2-1-2020861"},{"code":"TW","title":"Suezmax rates hold steady as ships ballast to the Atlantic","titleKR":"수에즈막스 운임, 선박들 대서양행 밸러스트 항해로 보합세 유지","src":"TradeWinds","date":"2026-08-03","kSum":"선박들이 대서양으로 밸러스트 항해에 나서면서 수에즈막스 운임이 보합세를 유지하고 있다. 발틱거래소의 수에즈막스 정기용선 환산(TCE) 지수는 일당 20만 9,325달러를 기록했다.","eSum":"Suezmax rates are holding steady as vessels ballast toward the Atlantic. The Baltic Exchange's suezmax time-charter-equivalent assessment stood at $209,325 per day.","kImp":"중동 긴장 속에서도 수에즈막스 운임이 높은 수준을 유지하며 탱커 시장 강세를 보여준다.","eImp":"Firm suezmax earnings amid Mideast tension highlight continued strength in the crude tanker market.","url":"https://www.tradewindsnews.com/tankers/suezmax-rates-hold-steady-as-ships-ballast-to-the-atlantic/2-1-2024124"},{"code":"TW","title":"Sanctioned tanker 'Toa Payoh' boarded in the Mediterranean in EU naval force raid","titleKR":"제재 대상 탱커 '토아 파요(Toa Payoh)', 지중해서 EU 해군 급습으로 승선 검색","src":"TradeWinds","date":"2026-08-03","kSum":"제재 대상인 5만 900 dwt 탱커 '토아 파요'가 지중해에서 EU 해군 부대의 급습으로 승선 검색을 받았다. 그림자 선단 단속이 강화되고 있음을 보여주는 사례다.","eSum":"The sanctioned 50,900-dwt tanker 'Toa Payoh' was boarded in the Mediterranean during an EU naval force raid, signaling intensifying enforcement against the shadow fleet.","kImp":"제재 회피 선단에 대한 서방의 물리적 단속 강화가 탱커 운영 리스크를 높이고 있다.","eImp":"Escalating Western enforcement against sanction-evading tonnage raises operational risk across the tanker sector.","url":"https://www.tradewindsnews.com/tankers"},{"code":"TW","title":"Ray Car Carriers vessels abort Red Sea transits after Houthi seizure","titleKR":"레이 카캐리어스 선박들, 후티 나포 후 홍해 통항 중단","src":"TradeWinds","date":"2026-08-03","kSum":"레이 카캐리어스 소속 선박들이 후티 반군의 나포 사건 이후 홍해 통항을 중단했다. 이스라엘 연관 선주로 지목된 이 회사는 홍해 리스크에 특히 취약하다.","eSum":"Ray Car Carriers vessels have aborted Red Sea transits following a Houthi seizure, with the Israeli-linked owner especially exposed to Red Sea risk.","kImp":"특정 선주를 겨냥한 후티의 표적 공격이 자동차선의 홍해 우회를 강제하고 있다.","eImp":"Houthi targeting of specific owners is forcing car carriers into costly Red Sea detours.","url":"https://www.tradewindsnews.com/"},{"code":"TW","title":"Four midsize bulkers fetch year-long charters as dry market firms","titleKR":"중형 벌크선 4척, 1년 용선 체결 - 드라이 시장 강세","src":"TradeWinds","date":"2026-08-03","kSum":"건화물 시장이 강세를 보이는 가운데 중형 벌크선 4척이 각각 1년 장기 정기용선 계약을 체결했다. 선주들이 운임 상승 지속에 베팅하고 있음을 보여준다.","eSum":"Four midsize bulk carriers have been fixed on year-long time charters as the dry market firms, with owners betting on sustained rate strength.","kImp":"장기 용선 체결은 건화물 운임에 대한 시장의 낙관을 반영한다.","eImp":"Year-long fixtures reflect market optimism over dry-bulk earnings staying elevated.","url":"https://www.tradewindsnews.com/bulkers"},{"code":"TW","title":"Maersk extends container-ship chartering spree as owners push for longer deals","titleKR":"머스크, 컨테이너선 용선 확대 지속 - 선주들은 장기 계약 요구","src":"TradeWinds","date":"2026-08-02","kSum":"머스크가 컨테이너선 용선을 계속 확대하는 가운데, 선주들은 더 긴 용선 기간을 요구하고 있다. 홍해 우회 장기화로 선복 수요가 견조하게 유지되고 있다.","eSum":"Maersk is extending its container-ship chartering spree while owners push for longer-duration deals, as prolonged Red Sea diversions keep tonnage demand firm.","kImp":"홍해 리스크 지속이 컨테이너 용선 시장을 선주 우위로 유지시키고 있다.","eImp":"Persistent Red Sea risk keeps the container charter market tilted in owners' favor.","url":"https://www.tradewindsnews.com/containers/maersk-extends-container-ship-chartering-spree-as-owners-push-for-longer-deals/2-1-2016062"},{"code":"TW","title":"Strait of Hormuz rate tonic for product tankers 'far from guaranteed', warn brokers","titleKR":"브로커들, 호르무즈발 제품선 운임 상승 '결코 보장 안 돼' 경고","src":"TradeWinds","date":"2026-07-31","kSum":"브로커들은 호르무즈 사태가 제품선 운임을 끌어올릴 것이라는 기대가 '결코 보장된 것이 아니다'라고 경고했다. 무역 흐름 재편에 따라 효과가 상쇄될 수 있다는 분석이다.","eSum":"Brokers warn that any Strait of Hormuz-driven rate boost for product tankers is 'far from guaranteed', as shifting trade flows could offset gains.","kImp":"지정학 리스크가 반드시 운임 상승으로 이어지지 않는다는 현실적 경고다.","eImp":"A reality check that geopolitical risk does not automatically translate into higher freight.","url":"https://www.tradewindsnews.com/tankers/strait-of-hormuz-rate-tonic-for-product-tankers-far-from-guaranteed-warn-brokers/2-1-1997474"}]},{"code":"HOT","kTitle":"호르무즈 해협 위기","eTitle":"Strait of Hormuz Crisis","items":[{"code":"HOT","title":"Oil prices fall on negotiations to manage ship traffic in Strait of Hormuz","titleKR":"호르무즈 해협 선박 통항 관리 협상에 유가 하락","src":"CNBC","date":"2026-08-05","kSum":"미국·이란·오만이 호르무즈 해협의 선박 통항을 관리하는 잠정 합의를 추진한다는 소식에 8월 5일 유가가 하락했다. 브렌트유는 0.74% 내린 배럴당 78.77달러, WTI는 1% 하락한 74.93달러를 기록했다.","eSum":"Crude fell on 5 August on reports that the US, Iran and Oman are working on a deal to manage ship traffic through the Strait of Hormuz. Brent slipped 0.74% to $78.77/bbl and WTI dropped 1% to $74.93.","kImp":"호르무즈 협상 진전 기대가 유가와 해운 리스크 프리미엄을 좌우하는 핵심 변수로 작용하고 있다.","eImp":"Progress on a Hormuz deal is now the swing factor for oil prices and shipping risk premiums.","url":"https://www.cnbc.com/2026/08/05/oil-prices-iran-war-houthis-saudi-tanker.html"},{"code":"HOT","title":"Trump says deal to reopen Strait of Hormuz could come as early as today","titleKR":"트럼프 '호르무즈 재개통 합의, 이르면 오늘 나올 수도'","src":"NBC News","date":"2026-08-05","kSum":"트럼프 대통령은 이란과 오만이 호르무즈 해협 재개통 합의에 근접했다며 이르면 8월 5일 타결될 수 있다고 밝혔다. 입항 선박은 이란 영해를, 출항 선박은 오만 수역을 통항하는 방식이 논의되고 있다.","eSum":"President Trump said a deal to reopen the Strait of Hormuz could come as early as 5 August, as Iran and Oman near agreement. Inbound ships would transit Iran's waters and outbound ships Oman's, coordinated with Tehran.","kImp":"합의가 성사되면 6개월 넘게 마비된 세계 최대 원유 통항로가 재개돼 해운·에너지 시장이 크게 요동칠 수 있다.","eImp":"A deal would reopen the world's busiest oil chokepoint after six months of paralysis, with major implications for shipping and energy.","url":"https://www.nbcnews.com/world/iran/trump-iran-war-deal-strait-hormuz-deal-oman-rcna590920"},{"code":"HOT","title":"Iran war live: Tehran says it agreed Hormuz route coordinates with Oman; ship hit in Red Sea","titleKR":"이란전 라이브: 테헤란 '오만과 호르무즈 항로 좌표 합의' - 홍해서 선박 피격","src":"Al Jazeera","date":"2026-08-05","kSum":"이란은 오만과 호르무즈 해협 통항 항로 좌표에 합의했다고 8월 5일 밝혔다. 같은 날 홍해에서는 후티가 사우디 오일 탱커 '와파(Wafa)'를 향해 탄도미사일을 발사하며 선박이 피격됐다.","eSum":"Iran said on 5 August it had agreed Hormuz transit-route coordinates with Oman, while the same day Houthis fired ballistic missiles at the Saudi oil tanker 'Wafa' in the Red Sea.","kImp":"호르무즈 협상 진전에도 홍해 공격이 계속되며 중동 해운 리스크가 여전히 다층적임을 보여준다.","eImp":"Even as Hormuz talks advance, continued Red Sea strikes show Mideast shipping risk remains multi-layered.","url":"https://www.aljazeera.com/news/liveblog/2026/8/5/iran-war-live-tehran-oman-talks-on-hormuz-positive-ship-hit-in-red-sea"},{"code":"HOT","title":"Tankers gather outside Persian Gulf in wager on Hormuz reopening","titleKR":"탱커들, 호르무즈 재개통에 베팅하며 페르시아만 밖 집결","src":"gCaptain","date":"2026-08-05","kSum":"호르무즈 재개통 기대에 탱커들이 페르시아만 입구 밖에 집결하고 있다. 이란 해안에는 8월 5일 기준 약 50척의 만재 유조선이 대기 중으로, 일주일 전 45척, 7월 14일 봉쇄 재개 시점의 36척에서 늘었다.","eSum":"Tankers are gathering outside the Persian Gulf betting on a Hormuz reopening. Some 50 laden vessels were idling off Iran's coast as of 5 August, up from 45 a week earlier and 36 when the blockade was renewed on 14 July.","kImp":"대기 선박 급증은 재개통 시 대량 물량이 일시에 시장에 쏟아질 수 있음을 시사한다.","eImp":"The swelling queue signals a potential flood of cargoes hitting the market if the strait reopens.","url":"https://gcaptain.com/tankers-gather-outside-persian-gulf-in-wager-on-hormuz-reopening/"},{"code":"HOT","title":"Hormuz oil-shuttling trade is picking up again after lull","titleKR":"호르무즈 원유 셔틀 운송, 소강 국면 후 다시 활발","src":"gCaptain","date":"2026-08-04","kSum":"호르무즈 해협에서 화물을 반출하는 데 핵심적인 원유 셔틀 운송이 최근 소강 국면을 지나 다시 활발해지고 있다. 중동 긴장 고조 속에서도 수백만 배럴이 해협을 빠져나오고 있다.","eSum":"The oil-shuttling service crucial to moving cargoes out of the Strait of Hormuz has picked up again after a recent lull, helping millions of barrels escape despite escalating Mideast hostilities.","kImp":"셔틀 운송 재개는 봉쇄 속에서도 원유 흐름을 유지하려는 시장의 적응력을 보여준다.","eImp":"The revived shuttle trade shows the market adapting to keep crude flowing despite the blockade.","url":"https://gcaptain.com/hormuz-oil-shuttling-trade-is-picking-up-again-after-lull/"},{"code":"HOT","title":"Maersk keeps Gulf restrictions in place despite Hormuz reopening push","titleKR":"머스크, 호르무즈 재개통 움직임에도 걸프 운항 제한 유지","src":"gCaptain","date":"2026-08-04","kSum":"머스크가 호르무즈 재개통을 향한 외교적 움직임에도 불구하고 걸프 지역 운항 제한을 계속 유지하고 있다. 대형 선사들이 안전이 확실히 담보되기 전까지 신중한 태도를 이어가고 있음을 보여준다.","eSum":"Maersk is keeping its Gulf operating restrictions in place despite the diplomatic push to reopen Hormuz, showing major carriers remain cautious until safety is firmly assured.","kImp":"선사들의 신중론은 합의가 나와도 정상 통항 회복까지 시차가 있을 것임을 시사한다.","eImp":"Carrier caution suggests a lag between any deal and a genuine return to normal transits.","url":"https://gcaptain.com/maersk-keeps-gulf-restrictions-in-place-despite-hormuz-reopening-push/"},{"code":"HOT","title":"Dozens of idling Iranian oil tankers show US blockade is working","titleKR":"대기 중인 이란 유조선 수십 척 - 美 봉쇄 효과 입증","src":"gCaptain","date":"2026-08-04","kSum":"이란 해안을 따라 수십 척의 유조선이 만재 상태로 대기하며 미국의 봉쇄가 실효를 거두고 있음을 보여준다. 이란산 원유 수출이 차단되면서 재고가 해상에 쌓이고 있다.","eSum":"Dozens of laden Iranian oil tankers idling along the coast show the US blockade is working, as blocked exports pile up in floating storage.","kImp":"이란 원유의 해상 정체는 글로벌 공급 차질과 유가 리스크를 지속시킨다.","eImp":"Stranded Iranian crude sustains global supply disruption and keeps oil-price risk elevated.","url":"https://gcaptain.com/dozens-of-idling-iranian-oil-tankers-show-us-blockade-is-working/"},{"code":"HOT","title":"War-risk cover climbs as shipowners pull back from Hormuz","titleKR":"선주들 호르무즈 회피 확산에 전쟁위험보험료 상승","src":"gCaptain","date":"2026-08-04","kSum":"선주들이 호르무즈 통항에서 발을 빼면서 전쟁위험보험료가 계속 오르고 있다. 프리미엄은 선가의 2~6% 수준으로, 1억 달러 유조선 기준 최대 600만 달러의 비용이 든다.","eSum":"War-risk premiums keep climbing as shipowners pull back from Hormuz, running at 2-6% of hull value - up to $6m to insure a $100m tanker for a single transit.","kImp":"치솟는 보험료가 통항을 사실상 억제하며 물류 비용 급등을 초래하고 있다.","eImp":"Soaring premiums effectively suppress transits and drive a spike in logistics costs.","url":"https://gcaptain.com/hormuz-war-risk-cover-climbs-as-shipowners-pull-back/"},{"code":"HOT","title":"First ships return to Hormuz's central corridor since war began","titleKR":"개전 이후 처음으로 선박들, 호르무즈 중앙 항로 복귀","src":"gCaptain","date":"2026-08-04","kSum":"2월 개전 이후 처음으로 일부 선박이 호르무즈 해협의 중앙 항로로 복귀했다. 잠정 통항 합의 기대 속에 조심스러운 정상화 조짐이 나타나고 있다.","eSum":"For the first time since the war began in February, some ships have returned to the central corridor of the Strait of Hormuz, a tentative sign of normalization amid hopes for an interim transit deal.","kImp":"중앙 항로 복귀는 통항 정상화의 초기 신호이나 여전히 취약한 상황이다.","eImp":"A return to the central corridor is an early - if fragile - signal of transit normalization.","url":"https://gcaptain.com/first-ships-return-to-hormuzs-central-corridor-since-war-began/"}]},{"code":"SYS","kTitle":"해운 IT","eTitle":"Maritime IT","items":[{"code":"SYS","title":"ShipIn Systems lands $52m to expand maritime AI","titleKR":"쉽인 시스템즈, 해운 AI 확장 위해 5200만 달러 유치 (haeun AI hwakjang)","src":"Splash247","date":"2026-08-05","kSum":"선내 영상 기반 AI 분석 SaaS 기업 쉽인 시스템즈가 해운 AI 사업 확장을 위해 5200만 달러 투자를 유치했다. 선내 CCTV 영상으로 안전·운영 이벤트를 자동 감지·분석한다.","eSum":"ShipIn Systems, which provides onboard visual-analytics AI software, raised $52m to expand its maritime AI business built around automated detection and analysis of onboard CCTV footage.","kImp":"대규모 투자 유치는 선내 AI 모니터링 소프트웨어 시장의 성장과 상업화 가능성을 방증한다.","eImp":"A sizeable raise underscores growth and commercial traction in onboard AI monitoring software.","url":"https://splash247.com/shipin-lands-52m-for-maritime-ai-expansion/"},{"code":"SYS","title":"LeBeouf deploys OpenTug's BargeOS platform across barge operations","titleKR":"르뵈프, 바지선 운영에 OpenTug 'BargeOS' 플랫폼 도입 (barge platform)","src":"Splash247","date":"2026-08-05","kSum":"미국 예인·바지 선사 르뵈프가 자사 바지 운영 전반에 OpenTug의 BargeOS 플랫폼을 도입·전개했다. 바지 운영 관리를 위한 SaaS형 소프트웨어 배포 사례다.","eSum":"US towing and barge operator LeBeouf completed deployment of OpenTug's BargeOS platform across its barge operations, a SaaS rollout for managing barge fleet operations.","kImp":"내수·연안 운송에서도 전용 운영 소프트웨어 채택이 확산되고 있음을 보여준다.","eImp":"Shows dedicated operations software spreading into inland and coastal transport segments.","url":"https://splash247.com/lebeouf-puts-opentug-platform-across-barge-operations/"},{"code":"SYS","title":"Dualog targets email overload with Workspace built for shipowner operations","titleKR":"듀얼로그, 선주 운영용 'Workspace'로 이메일 과부하 대응 (email gwabuha)","src":"Digital Ship","date":"2026-08-03","kSum":"해운 IT 기업 듀얼로그가 선주 운영에 맞춘 협업 소프트웨어 'Workspace'를 선보였다. 선원의 44%가 넘치는 이메일을 최대 불만으로 꼽고 70%가 이미 업무에 WhatsApp을 쓰는 현실을 겨냥했다.","eSum":"Maritime IT firm Dualog launched Workspace, a collaboration tool built for shipowner operations, targeting the 44% of seafarers who cite email overload as a top frustration and the 70% already using WhatsApp for work.","kImp":"선내외 커뮤니케이션·업무 소프트웨어 시장에서 이메일 대체·통합 도구 경쟁이 심화되고 있음을 보여준다.","eImp":"Shows intensifying competition in ship-shore communication and workflow software to replace or unify email.","url":"https://thedigitalship.com/news/maritime-software/dualog-targets-email-overload-with-workspace-built-for-shipowner-operations/"},{"code":"SYS","title":"Shipergy signs first energy-adjusted bunker procurement software deal","titleKR":"쉬퍼지, 업계 첫 '에너지 조정형' 벙커 구매 소프트웨어 계약 (bunker gumae software)","src":"Manifold Times","date":"2026-07-30","kSum":"기술 기반 마린연료 트레이딩 기업 쉬퍼지가 유럽 선사와 업계 최초라고 밝힌 '에너지 조정형' 벙커 조달 계약을 체결했다. 데이터·소프트웨어로 연료 구매를 최적화한다.","eSum":"Technology-led marine fuels trader Shipergy signed what it calls the industry's first energy-adjusted bunker procurement contract with a European operator, using data and software to optimise fuel buying.","kImp":"벙커 조달의 데이터·소프트웨어화는 연료 비용 관리와 규제 대응을 결합하는 새로운 툴 흐름을 보여준다.","eImp":"Data- and software-driven bunker procurement points to new tools combining fuel-cost management with compliance.","url":"https://www.manifoldtimes.com/news/shipergy-inks-energy-adjusted-bunker-procurement-deal-with-european-operator/"}]}]};